L["Apply the sharer's Blizz UI Enhanced Window Skins and Tooltips, Menus & Popups settings. These are account-wide and will overwrite yours across ALL profiles. Off = keep your own."] = "공유자의 Blizz UI 향상 창 스킨과 툴팁, 메뉴 및 팝업 설정을 적용합니다. 이 설정은 계정 전체에 적용되며 모든 프로필에서 내 설정을 덮어씁니다. 끄면 내 설정을 유지합니다."
