L["Pins this block's content to the exact center of the bar; blocks before it pack left, blocks after pack right. Combined with Fill Remaining, the block also absorbs the leftover space around the center."] = "항목 내용을 바의 정중앙에 고정합니다. 앞 항목은 왼쪽으로, 뒤 항목은 오른쪽으로 정렬됩니다. '남은 공간 채움'과 함께 쓰면 중앙 주변의 남는 공간도 이 항목이 흡수합니다."
