L["Hold Shift to scroll to the top or bottom."] = "Shift를 누르면 맨 위나 맨 아래로 스크롤합니다."
L["Hold the key to open, release to fire. Toggle mode keeps the menu open: the Select key fires, the menu key or Escape closes."] = "키를 누르고 있으면 열리고 놓으면 발동합니다. 전환 모드에서는 메뉴가 열린 채 유지됩니다: 선택 키로 발동, 메뉴 키나 Escape로 닫기."
