L["The tracker always hides in arenas"] = "추적기는 투기장에서 항상 숨겨집니다"
L["Thickness in pixels. -1 follows each debuff indicator's Border setting, 0 hides the dispel color border."] = "두께(픽셀). -1은 각 약화 효과 표시기의 테두리 설정을 따르고, 0은 해제 색상 테두리를 숨깁니다."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\n"] = "이 기능은 높은 FPS와 시각적 선명도의 최적 조합을 위해 게임 내 그래픽 설정을 최적화합니다.\n\n최적화 후 나타나는 \"내 설정 복원\"을 클릭하여 언제든지 모든 변경 사항을 되돌릴 수 있습니다.\n\n\n변경 항목:\n\n"
L["This glow is locked on its settings page."] = "이 반짝임은 해당 설정 페이지에서 고정되어 있습니다."
L["This is a CDM Bar Layout string, not a profile string."] = "이것은 프로필 문자열이 아니라 CDM 바 레이아웃 문자열입니다."
L["This is an old CDM Bar Layout string. This format is no longer supported. Use the standard profile import instead."] = "이것은 이전 CDM 바 레이아웃 문자열입니다. 이 형식은 더 이상 지원되지 않습니다. 일반 프로필 가져오기를 사용하세요."
L["This option only affects Raid Buffs you can cast"] = "이 옵션은 자신이 시전할 수 있는 공격대 강화 효과에만 적용됩니다"
L["This option only applies to the Badge style."] = "이 옵션은 배지 스타일에만 적용됩니다."
L["This option only applies when Name > Target is selected."] = "이 옵션은 이름 > 대상이 선택된 경우에만 적용됩니다."
L["This option only applies when Name > Target or Target is selected."] = "이 옵션은 이름 > 대상 또는 대상이 선택된 경우에만 적용됩니다."
L["This option only applies when Target is selected."] = "이 옵션은 대상이 선택된 경우에만 적용됩니다."
L["This option only applies when the text shows a name."] = "이 옵션은 글자에 이름이 표시될 때만 적용됩니다."
