L["This option requires Custom Border Style, Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "이 옵션은 사용자 지정 테두리 모양, 아이콘 표시, 아이콘을 바의 일부로 만들기 및 EllesmereUI 스타일이 필요합니다."
L["This option requires Dispel Type Borders to be enabled."] = "이 옵션은 해제 유형 테두리가 활성화되어 있어야 합니다."
L["This option requires Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "이 옵션은 아이콘 표시, 아이콘을 바의 일부로 만들기 및 EllesmereUI 스타일이 필요합니다."
