L["Native: the client's dark square sweep. Shaped: a drawn sweep that follows round icons and takes the Swipe Color."] = "기본: 클라이언트의 어두운 사각형 회전 효과입니다. 모양: 둥근 아이콘을 따라 그려지며 회전 효과 색상을 사용하는 회전 효과입니다."
L["Nest Distance"] = "중첩 거리"
L["Nest Distance and Size"] = "중첩 거리 및 크기"
L["Nest Icon Size"] = "중첩 아이콘 크기"
L["No DataBars"] = "데이터 바 없음"
L["One Window"] = "창 하나"
L["Only Dispellable"] = "해제 가능한 것만"
L["Only Group & Pull"] = "그룹 및 전투 준비만"
L["Only Markers"] = "징표만"
L["Own and Raid Debuffs"] = "내 약화 효과 및 공격대 약화 효과"
L["Own Keybind"] = "자체 단축키"
L["Percent of the end caps' normal size."] = "끝 장식 기본 크기에 대한 백분율입니다."
L["Picks an NPC's only dialog option for you."] = "NPC의 대화 선택지가 하나뿐일 때 자동으로 선택합니다."
L["Player Buffs on Tooltips"] = "툴팁에 플레이어 강화 효과"
L["Positive values move both end caps away from the bar."] = "양수 값은 양쪽 끝 장식을 바에서 멀어지게 합니다."
L["Primary Spec"] = "주 특성"
L["PULL TIMER"] = "전투 준비 타이머"
L["Pushes older messages along so a new one never overlaps them."] = "새 메시지가 겹치지 않도록 이전 메시지를 밀어냅니다."
L["Quest XP Overlay"] = "퀘스트 경험치 오버레이"
L["Raid Debuffs Filter"] = "공격대 약화 효과 필터"
L["Raid Debuffs shows the common raid debuffs (armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements, Hunter's Mark) from anyone."] = "공격대 약화 효과는 누가 걸었든 일반적인 공격대 약화 효과(방어도, 받는 주문 및 물리 피해, 받는 치명타, 전투력, 공격 및 시전 속도, 받는 치유량, 심판, 사냥꾼의 징표)를 표시합니다."
L["Reads the item's own stats; enchants and gems are not counted."] = "아이템 자체 능력치만 읽으며, 마법부여와 보석은 계산되지 않습니다."
L["Reload to finish resetting EUI."] = "EUI 초기화를 완료하려면 재시작하세요."
L["Reload to finish uninstalling EUI."] = "EUI 제거를 완료하려면 재시작하세요."
L["Rename DataBar"] = "데이터 바 이름 변경"
L["Rested After Quest XP"] = "퀘스트 경험치 이후 휴식"
L["Rested color"] = "휴식 색상"
L["Return every EUI addon to its defaults."] = "모든 EUI 애드온을 기본값으로 되돌립니다."
L["Revert EUI's changes and disable."] = "EUI의 변경 사항을 되돌리고 비활성화합니다."
L["Right Endcap"] = "오른쪽 끝 장식"
L["Scroll Distance"] = "스크롤 거리"
L["Second Timer"] = "두 번째 타이머"
L["Secondary Spec"] = "보조 특성"
L["Selection Color"] = "선택 색상"
L["Selection Color: Custom Color"] = "선택 색상: 사용자 지정 색상"
L["SELF COMBAT TEXT"] = "자신 전투 글자"
L["Self Combat Text"] = "자신 전투 글자"
L["Sell Junk skips items with no vendor price, equipment set gear and pinned items."] = "잡동사니 판매는 상점 판매 가격이 없는 아이템, 장비 구성 아이템, 고정된 아이템을 건너뜁니다."
L["Shaped"] = "모양"
L["Shaped Cooldown Swipe"] = "모양 재사용 대기시간 회전 효과"
L["Share Keybind With"] = "단축키 공유 대상"
L["Shift + Click World Markers"] = "Shift + 클릭 위치 표시기"
L["Shift + Left Click a marker icon to use its world marker item, then click the ground. Only markers whose item is in your bags get it; the rest keep Shift + Click to clear the target marker. Shift + Left Click the clear icon presses the server's Reset Markers button."] = "징표 아이콘을 Shift + 왼쪽 클릭하면 해당 위치 표시기 아이템을 사용하며, 그다음 바닥을 클릭하세요. 아이템이 가방에 있는 징표만 적용되며, 나머지는 Shift + 클릭으로 대상 징표를 지우는 기능을 유지합니다. 지우기 아이콘을 Shift + 왼쪽 클릭하면 서버의 징표 초기화 버튼을 누릅니다."
L["Show a small coin in the corner of items marked as junk."] = "잡동사니로 표시된 아이템 모서리에 작은 동전을 표시합니다."
L["Show at Max Level"] = "최고 레벨에서 표시"
L["Show Coin on Junk"] = "잡동사니에 동전 표시"
L["Show Convert to Raid"] = "공격대로 전환 표시"
L["Show Dividers"] = "구분선 표시"
L["Show Equipped Item Color"] = "착용 아이템 색상 표시"
L["Show Inspect Enchant Names Instead of Icons"] = "살펴보기에서 아이콘 대신 마법부여 이름 표시"
L["Show Item Icon Name"] = "아이템 아이콘 이름 표시"
L["Show Item ID on Tooltip"] = "툴팁에 아이템 ID 표시"
L["Show Player Buffs"] = "플레이어 강화 효과 표시"
L["Show Reinvite"] = "재초대 표시"
L["Show Rested XP"] = "휴식 경험치 표시"
L["Show Target Name"] = "대상 이름 표시"
L["Show the coin button in the bag header. Click it, then click items to mark or unmark them as junk. Junk goes into its own Junk category, and a Sell Junk button appears next to the coin while a merchant is open."] = "가방 상단에 동전 버튼을 표시합니다. 버튼을 클릭한 다음 아이템을 클릭하여 잡동사니로 표시하거나 해제합니다. 잡동사니는 별도의 잡동사니 분류로 들어가며, 상인 창이 열려 있으면 동전 옆에 잡동사니 판매 버튼이 나타납니다."
L["Shown at max level. Profession bonuses are only checked on your own sheet."] = "최고 레벨에서 표시됩니다. 전문 기술 보너스는 자신의 캐릭터 정보 창에서만 확인됩니다."
L["Shows the common raid debuffs from anyone: armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements and Hunter's Mark."] = "누가 걸었든 일반적인 공격대 약화 효과를 표시합니다: 방어도, 받는 주문 및 물리 피해, 받는 치명타, 전투력, 공격 및 시전 속도, 받는 치유량, 심판, 사냥꾼의 징표."
L["Shows the Convert to Raid button. In a raid of five or fewer it reads Convert to Party: everyone is removed and invited back to a new party."] = "공격대로 전환 버튼을 표시합니다. 5명 이하의 공격대에서는 파티로 전환으로 표시되며, 모두를 내보낸 뒤 새 파티로 다시 초대합니다."
L["Shows the debuffs you apply plus the common raid debuffs from anyone."] = "자신이 건 약화 효과와 누가 걸었든 일반적인 공격대 약화 효과를 표시합니다."
L["Shows the Disband button. It always asks before disbanding, but hiding it puts it out of misclick range for good."] = "해체 버튼을 표시합니다. 해체 전에 항상 확인을 요청하지만, 숨기면 실수로 누를 일이 아예 없어집니다."
L["Shows the hovered player's buffs as icons next to the tooltip (up to 16)."] = "마우스를 올린 플레이어의 강화 효과를 툴팁 옆에 아이콘으로 표시합니다 (최대 16개)."
L["Shows the overlay, type icon and border colors only for debuffs you can currently dispel."] = "현재 해제할 수 있는 약화 효과에만 오버레이, 유형 아이콘, 테두리 색상을 표시합니다."
L["Shows the Reinvite button. It asks first, then removes everyone and invites them back to the same kind of group. Players have to accept the new invite."] = "재초대 버튼을 표시합니다. 먼저 확인을 요청한 뒤 모두를 내보내고 같은 종류의 그룹으로 다시 초대합니다. 플레이어는 새 초대를 수락해야 합니다."
L["Shows your damage taken, healing, avoids and combat enter/leave above the player frame instead of Blizzard's combat text, whose other messages are hidden while this is on. Move it in Unlock Mode."] = "블리자드 전투 글자 대신 받은 피해, 치유, 회피, 전투 시작/종료를 플레이어 프레임 위에 표시합니다. 이 기능이 켜져 있는 동안 블리자드 전투 글자의 다른 메시지는 숨겨집니다. 잠금 해제 모드에서 이동하세요."
L["Smart Ticks"] = "스마트 눈금"
L["Spell IDs in the Breakdown"] = "세부 내역에 주문 ID"
L["Stagger Hits"] = "타격 분산"
L["Stat Hover Highlight"] = "능력치 마우스 오버 강조"
L["Static"] = "고정"
L["Straight"] = "직선"
L["Style Page Look Menus"] = "스타일 페이지 모양 메뉴"
L["Swipe Color"] = "회전 효과 색상"
L["Swipe Style"] = "회전 효과 스타일"
L["Tank Name"] = "탱커 이름"
L["Text Shadow"] = "글자 그림자"
L["The [Merfin] Experience Bar (Luxthos) WeakAura: blue to purple gradient, Quest XP Overlay, spark, rested after quest XP and seven texts with level, times and time to level."] = "[Merfin] Experience Bar (Luxthos) WeakAura: 파란색에서 보라색으로 이어지는 그라데이션, 퀘스트 경험치 오버레이, 반짝이, 퀘스트 경험치 이후 휴식, 레벨·시간·레벨업까지 남은 시간을 담은 7개의 글자."
L["The classic tooltip box around the meter window, with vanilla header buttons and every EllesmereUI meter feature."] = "미터기 창 주위의 클래식 툴팁 상자로, 기본 UI 머리글 버튼과 모든 EllesmereUI 미터기 기능을 갖추고 있습니다."
L["The gap between a nested menu's icons and the entry that opens it."] = "중첩 메뉴의 아이콘과 그 메뉴를 여는 항목 사이의 간격입니다."
L["The rested segment starts where the Quest XP Overlay ends instead of at your current XP."] = "휴식 구간이 현재 경험치가 아니라 퀘스트 경험치 오버레이가 끝나는 지점에서 시작됩니다."
L["The talent group this action menu works in. Outside it the keybind does nothing and the menu is hidden where it is nested."] = "이 동작 메뉴가 작동하는 특성 그룹입니다. 그 밖에서는 단축키가 아무 동작도 하지 않으며, 중첩된 위치에서 메뉴가 숨겨집니다."
L["Third Timer"] = "세 번째 타이머"
L["This option requires an EllesmereUI Focus frame."] = "이 설정에는 EllesmereUI 주시 대상 프레임이 필요합니다."
L["This option requires XP Bar Style EllesmereUI or Luxthos"] = "이 설정에는 경험치 바 스타일 EllesmereUI 또는 Luxthos가 필요합니다"
L["Time This Session and XP per Hour carry on through a /reload (a load within five minutes) instead of starting over."] = "이번 세션 시간과 시간당 경험치가 처음부터 다시 시작하지 않고 /reload(5분 이내의 재접속) 후에도 이어집니다."
L["Timed Buffs"] = "시간제 강화 효과"
L["Toggle Raid Tools"] = "공격대 도구 전환"
L["Toggles the Raid Tools panels, in or out of combat.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "전투 중이든 아니든 공격대 도구 창을 켜고 끕니다.\n\n왼쪽 클릭으로 단축키를 지정합니다.\n오른쪽 클릭으로 단축키를 해제합니다."
L["Two Windows"] = "창 두 개"
L["Uninstall & Reload"] = "제거 및 재시작"
L["Uninstall EUI"] = "EUI 제거"
L["Up Left"] = "왼쪽 위"
L["Up Right"] = "오른쪽 위"
L["Use another action menu's keybind while that menu is not loaded. Both menus must be assigned to different specs."] = "해당 메뉴가 불러와지지 않은 동안 다른 동작 메뉴의 단축키를 사용합니다. 두 메뉴는 서로 다른 특성에 할당되어야 합니다."
L["Which buffs enemy nameplates show. Fine-tune it on the Aura Filters page."] = "적 이름표에 표시할 강화 효과입니다. 오라 필터 페이지에서 세부 조정하세요."
L["Which ends of the bar show the gryphons."] = "그리핀을 표시할 바의 끝 방향입니다."
L["XP Bar Style"] = "경험치 바 스타일"
L["XP color"] = "경험치 색상"
L["Every module runs on native Wrath APIs. Retail looks and settings were ported wherever the 3.3.5a client supports them, and Retail-only systems were left out. Notes are grouped by module, newest first, and each header shows that module's backport version."] = "모든 모듈은 리치 왕의 분노 기본 API로 작동합니다. 리테일의 모양과 설정은 3.3.5a 클라이언트가 지원하는 곳이면 모두 이식했으며, 리테일 전용 시스템은 제외했습니다. 노트는 모듈별로 최신순으로 묶여 있으며, 각 머리글에 해당 모듈의 백포트 버전이 표시됩니다."
L["Icons beside each enemy for every crowd control category they are under or recovering from: green means the next one lasts half as long, yellow a quarter, red immune. A timer shows the 18 second reset."] = "각 적 옆에 현재 걸려 있거나 회복 중인 군중 제어 분류마다 아이콘이 표시됩니다: 녹색은 다음 효과가 절반, 노란색은 4분의 1만 지속되며, 빨간색은 면역입니다. 18초 초기화 타이머가 표시됩니다."
L["A health bar for each enemy pet under its owner's frame. Left-click targets the pet, right-click sets focus."] = "각 적 소환수의 생명력 바가 주인 프레임 아래에 표시됩니다. 왼쪽 클릭으로 소환수를 대상으로 지정하고, 오른쪽 클릭으로 주시 대상으로 지정합니다."
L["Enemy frames for arena1-5 with class colored health, power and cast bars plus a highlight on your target. Left-click targets, right-click sets focus. There is no Retail equivalent."] = "arena1-5용 적 프레임으로, 직업 색상 생명력 바, 자원 바, 시전 바와 내 대상 강조 표시가 있습니다. 왼쪽 클릭으로 대상 지정, 오른쪽 클릭으로 주시 대상 지정. 리테일에는 해당 기능이 없습니다."
L["The class icon swaps to the highest priority crowd control or immunity with a spiral and timer, and the PvP trinket icon tracks its 2 minute cooldown from the combat log."] = "직업 아이콘이 우선순위가 가장 높은 군중 제어나 면역 효과로 바뀌며 회전 효과와 타이머가 표시되고, PvP 장신구 아이콘은 전투 기록으로 2분 재사용 대기시간을 추적합니다."
L["Bar Texture lists textures from SharedMedia and other addons using LibSharedMedia"] = "바 텍스처에 SharedMedia 및 LibSharedMedia를 사용하는 다른 애드온의 텍스처가 표시됩니다"
L["Enemies beyond your class's 30-40 yard spell range fade to a chosen opacity"] = "내 직업의 30-40미터 주문 사거리 밖에 있는 적은 선택한 투명도로 흐려집니다"
L["Preview 2 to 5 sample frames in Unlock Mode, while the options page is open, or with /earena test"] = "잠금 해제 모드, 설정 페이지가 열려 있을 때, 또는 /earena test로 2~5개의 예시 프레임을 미리 봅니다"
L["Frames stay up while an enemy is stealthed or out of sight, dimmed and marked Unseen"] = "적이 은신 중이거나 시야 밖에 있어도 프레임이 흐리게 유지되며 보이지 않음으로 표시됩니다"
L["Optionally hides Blizzard's arena frames while these are in use"] = "이 프레임을 사용하는 동안 블리자드 투기장 프레임을 선택적으로 숨깁니다"
L["The Debuff Filter gets Raid Debuffs and Own and Raid Debuffs, with the same raid debuff list as the Unit Frames."] = "약화 효과 필터에 공격대 약화 효과와 내 약화 효과 및 공격대 약화 효과가 추가되며, 유닛 프레임과 같은 공격대 약화 효과 목록을 사용합니다."
L["Choose which buffs enemy nameplates show: Timed Buffs, Only Dispellable or Show All, which shows every buff."] = "적 이름표에 표시할 강화 효과를 선택합니다: 시간제 강화 효과, 해제 가능한 것만, 또는 모든 강화 효과를 보여주는 모두 표시."
L["Every nameplate text has an Outline choice under its Size: None, Outline, Thick Outline or Shadow, or keep the module default. Covers names, level, health, Target of Target, cast texts, aura text and friendly names."] = "모든 이름표 글자는 크기 아래에 외곽선 선택이 있습니다: 없음, 외곽선, 굵은 외곽선, 그림자, 또는 모듈 기본값 유지. 이름, 레벨, 생명력, 대상의 대상, 시전 글자, 오라 글자, 아군 이름에 적용됩니다."
L["Cast bars now fill every frame instead of stepping with each nameplate refresh. The spark and timer move smoothly too, and the extra work stops when no cast is visible."] = "시전 바가 이름표 갱신마다 끊기지 않고 매 프레임 부드럽게 채워집니다. 반짝이와 타이머도 부드럽게 움직이며, 보이는 시전이 없으면 추가 작업이 멈춥니다."
L["Core Text Positions offers all Retail texts: Enemy Name, Level | Name, Target of Target, Health % and Health # with their combined variants. Each text's cog sets its size."] = "핵심 글자 위치에서 리테일의 모든 글자를 제공합니다: 적 이름, 레벨 | 이름, 대상의 대상, 생명력 %와 생명력 수치 및 그 조합. 각 글자의 톱니바퀴에서 크기를 설정합니다."
L["Health and cast bars offer the EllesmereUI textures (Melli, Atrocity, Fade, Matte and more), as on Retail"] = "생명력 바와 시전 바에서 리테일처럼 EllesmereUI 텍스처(Melli, Atrocity, Fade, Matte 등)를 제공합니다"
L["Health and cast bar textures include textures from SharedMedia and other addons"] = "생명력 바와 시전 바 텍스처에 SharedMedia 및 다른 애드온의 텍스처가 포함됩니다"
L["Display and Colors show a live preview plate; click any part of it to jump to its setting"] = "표시와 색상에 실시간 미리보기 이름표가 표시됩니다. 원하는 부분을 클릭하면 해당 설정으로 이동합니다"
L["Retail bar size, colors, threat modes, cast colors, target arrows and Execute Pulse Glow"] = "리테일의 바 크기, 색상, 위협 수준 모드, 시전 색상, 대상 화살표 및 마격 발광"
L["Each slot holds one element; auras, raid marker and classification can also sit below the cast bar"] = "각 칸에는 요소 하나가 들어가며, 오라, 공격대 징표, 등급 표시는 시전 바 아래에도 배치할 수 있습니다"
L["Health # uses Blizzard style abbreviations (1.2K, 12K, 1.2M) with an optional % decimal"] = "생명력 수치는 블리자드 방식의 축약(1.2K, 12K, 1.2M)을 사용하며, 선택적으로 % 소수점을 표시합니다"
L["A profile imported from Retail no longer blows the target nameplate up to fill the screen."] = "리테일에서 가져온 프로필이 더 이상 대상 이름표를 화면 가득 확대하지 않습니다."
L["Border None now hides only the borders, not the cast bar text, timer, shield and kick mark."] = "테두리 없음은 이제 테두리만 숨기며, 시전 바 글자, 타이머, 보호막, 차단 표시는 숨기지 않습니다."
L["The options preview plate no longer disappears after switching tabs or closing the panel."] = "설정 미리보기 이름표가 탭을 전환하거나 창을 닫은 후 더 이상 사라지지 않습니다."
L["The Interrupt on CD cast color now shows while your interrupt recharges, as on Retail, instead of the reverse."] = "차단기 재사용 대기시간 중 시전 색상이 이제 리테일처럼 차단기가 재충전되는 동안 표시되며, 반대로 표시되지 않습니다."
L["Raid and party names each get their own outline: None, Outline, Thick Outline, Shadow, or the Raid Frames font default."] = "공격대와 파티 이름에 각각 외곽선을 설정할 수 있습니다: 없음, 외곽선, 굵은 외곽선, 그림자, 또는 공격대 프레임 글꼴 기본값."
L["A new Group Layout stacks two raid groups per column, then starts the next column to the right, so a 20-player raid forms a 2x2 block."] = "새 그룹 레이아웃은 열마다 공격대 그룹 두 개를 쌓은 뒤 오른쪽에 다음 열을 시작하므로, 20인 공격대는 2x2 블록이 됩니다."
L["Ready check icons appear above debuffs and keep each player result for ten seconds after the check finishes."] = "준비 확인 아이콘이 약화 효과 위에 표시되며, 확인이 끝난 후에도 10초 동안 각 플레이어의 결과를 유지합니다."
L["The debuff displayed in the central Raid Debuff icon is excluded from the regular debuff bar, leaving room for other debuffs."] = "중앙 공격대 약화 효과 아이콘에 표시된 약화 효과는 일반 약화 효과 바에서 제외되어 다른 약화 효과를 위한 공간이 생깁니다."
L["Raid and party frames dim outside range on Wrath, including in combat. Dim Out of Range and Out of Range Alpha control the fade."] = "리치 왕의 분노에서 공격대 및 파티 프레임이 전투 중에도 사거리 밖이면 흐려집니다. 사거리 밖 흐리게와 사거리 밖 투명도로 흐림을 조절합니다."
L["A large icon in the middle of each frame for important ICC, Ruby Sanctum, Trial of the Crusader, Ulduar and Naxxramas debuffs, highest priority first, with timer, stacks and a dispel colored border. Without a listed debuff it can show a dispellable one instead."] = "얼음왕관 성채, 루비 성소, 십자군의 시험장, 울두아르, 낙스라마스의 중요한 약화 효과를 각 프레임 중앙에 큰 아이콘으로 우선순위 높은 순서대로 표시하며, 타이머, 중첩, 해제 색상 테두리가 있습니다. 목록에 있는 약화 효과가 없으면 대신 해제 가능한 약화 효과를 표시할 수 있습니다."
L["Dispel Overlay styles with opacity, a dispel colored Frame Border, Type Icon Position, per-type Dispel Colors and Only Show Dispellable."] = "투명도가 있는 해제 오버레이 스타일, 해제 색상 프레임 테두리, 유형 아이콘 위치, 유형별 해제 색상 및 해제 가능만 표시."
L["Overlay, Real or No Preview. The preview opens while the Raid or Party page is open and closes when you leave it, close the panel or enter combat."] = "오버레이, 실제 또는 미리보기 없음. 미리보기는 공격대 또는 파티 페이지가 열려 있을 때 열리고, 페이지를 떠나거나 창을 닫거나 전투에 들어가면 닫힙니다."
L["Enemy casts show as icons on the party or raid member being cast at, with a cast sweep and interruptible border. Party defaults to When Healing; each raid layout has its own mode. Wrath has no spell target, so the victim is the caster's target, and only enemies someone in the group targets are seen"] = "적의 시전이 시전 대상인 파티원 또는 공격대원에게 아이콘으로 표시되며, 시전 회전 효과와 차단 가능 테두리가 있습니다. 파티 기본값은 힐러일 때 표시이며, 각 공격대 레이아웃은 자체 모드를 가집니다. 리치 왕의 분노에는 주문 대상 정보가 없어 시전자의 대상을 피해자로 간주하며, 그룹의 누군가가 대상으로 잡은 적만 보입니다"
L["Damage shields show on the health bar as on Retail: Absorb Style, Opacity, Color, Placement and Show Overshield. Wrath does not report shield amounts, so they are estimated from the combat log"] = "피해 보호막이 리테일처럼 생명력 바에 표시됩니다: 흡수 모양, 투명도, 색상, 배치, 초과 보호막 표시. 리치 왕의 분노는 보호막 수치를 알려주지 않으므로 전투 기록으로 추정합니다"
L["Health Bar Texture lists textures from SharedMedia and other addons, also in the aura indicator preview"] = "생명력 바 텍스처에 SharedMedia 및 다른 애드온의 텍스처가 표시되며, 오라 표시기 미리보기에도 적용됩니다"
L["25-Player Preview"] = "25인 미리보기"
L["The Unlock Mode and options previews open on the 25-player layout instead of 40"] = "잠금 해제 모드와 설정 미리보기가 40인 대신 25인 레이아웃으로 열립니다"
L["Health color modes, backgrounds, threat, target and hover borders, text and icon placement"] = "생명력 색상 모드, 배경, 위협 수준, 대상 및 마우스 오버 테두리, 글자 및 아이콘 배치"
L["Incoming heals and resurrections from players who use a HealComm addon"] = "HealComm 애드온을 사용하는 플레이어의 받을 치유와 부활"
L["Main Tank, Pet and Friendly Boss frames plus Healer Mana text, each with an Unlock Mode mover"] = "메인 탱커, 소환수, 우호적 우두머리 프레임과 힐러 마나 글자, 각각 잠금 해제 모드 이동 핸들 포함"
L["The Party page has a LAYOUT section with Horizontal Frames"] = "파티 페이지에 가로 프레임이 있는 배치 섹션이 생겼습니다"
L["Ready check icons show a green check for players who accepted and for the one who started the check, instead of a red X when the check ended."] = "준비 확인 아이콘이 수락한 플레이어와 확인을 시작한 플레이어에게 확인이 끝났을 때 빨간 X 대신 녹색 체크로 표시됩니다."
L["The party leader icon shows on the leader only instead of on several party members."] = "파티장 아이콘이 여러 파티원이 아닌 파티장에게만 표시됩니다."
L["Set Focus and Clear Focus in the raid and party frame menu work out of combat without the 'blocked from an action' popup; in combat they are hidden, use a Click Casting Focus binding there."] = "공격대 및 파티 프레임 메뉴의 주시 대상 지정과 주시 대상 해제가 전투 밖에서 '동작이 차단되었습니다' 팝업 없이 작동합니다. 전투 중에는 숨겨지므로, 그때는 클릭 시전 주시 대상 단축키를 사용하세요."
L["Ready check icons show on raid and party frames again."] = "준비 확인 아이콘이 공격대 및 파티 프레임에 다시 표시됩니다."
L["Hide Sated / Exhaustion also hides the 81005 Bloodlust lockout debuff."] = "만족함 / 탈진 숨기기가 81005 피의 욕망 잠금 약화 효과도 숨깁니다."
L["Pet frames no longer throw a SecureTemplates strupper error when they first appear."] = "소환수 프레임이 처음 나타날 때 더 이상 SecureTemplates strupper 오류가 발생하지 않습니다."
L["The Buffs/Debuffs editor's Add New menu no longer closes on the first click."] = "강화/약화 효과 편집기의 새로 추가 메뉴가 첫 클릭에 더 이상 닫히지 않습니다."
L["Element Options for raid and party frames now open the matching settings."] = "공격대 및 파티 프레임의 요소 설정이 이제 해당하는 설정을 엽니다."
L["Profile strings exported from Retail EllesmereUI import everything this client supports: each module keeps its current settings and takes the Retail values it understands. Retail-only modules, spec setups and Cooldown Manager spells are skipped, and chat reports how many settings came in."] = "리테일 EllesmereUI에서 내보낸 프로필 문자열은 이 클라이언트가 지원하는 모든 것을 가져옵니다: 각 모듈은 현재 설정을 유지하면서 이해할 수 있는 리테일 값을 받아들입니다. 리테일 전용 모듈, 전문화 설정, 재사용 대기시간 관리자 주문은 건너뛰며, 대화창에 가져온 설정 수를 알려줍니다."
L["A button on Global Settings puts back the game settings EUI changed (nameplate, minimap, chat and tooltip options, chat font sizes and keys Quickdraw took), then turns EUI off for this character and reloads. Your profiles are kept."] = "전체 설정의 버튼으로 EUI가 바꾼 게임 설정(이름표, 미니맵, 대화, 툴팁 설정, 대화 글꼴 크기, 빠른 실행이 가져간 키)을 되돌린 뒤, 이 캐릭터에서 EUI를 끄고 재시작합니다. 프로필은 유지됩니다."
L["A drawn cooldown sweep for modules that want round or colored swipes; the Wrath client's own swipe is always a dark square. Cooldown Manager uses it first."] = "둥글거나 색이 있는 회전 효과가 필요한 모듈을 위해 직접 그리는 재사용 대기시간 회전 효과입니다. 리치 왕의 분노 클라이언트 자체의 회전 효과는 항상 어두운 사각형입니다. 재사용 대기시간 관리자가 가장 먼저 사용합니다."
L["When a guild or group member runs a newer EllesmereUI release, chat tells you once per session. Type /euiupdate for the download link. Wrath has no internet access, so the news comes from other EUI users."] = "길드원이나 그룹원이 더 새로운 EllesmereUI 릴리스를 사용하면 세션당 한 번 대화창에 알려줍니다. /euiupdate를 입력하면 다운로드 링크가 표시됩니다. 리치 왕의 분노에는 인터넷 접속이 없으므로 소식은 다른 EUI 사용자에게서 옵니다."
L["The Locales addon provides community translations for all original Wrath client languages, with English fallback and Lua 5.1 formatting."] = "Locales 애드온은 리치 왕의 분노 클라이언트의 모든 원래 언어에 대한 커뮤니티 번역을 제공하며, 영어 대체 및 Lua 5.1 형식을 지원합니다."
L["The collapsed menu displays the original Ellesmere E logo with the UI accent color and a working close icon on the Wrath client."] = "접힌 메뉴에 UI 강조 색상의 원래 Ellesmere E 로고와 리치 왕의 분노 클라이언트에서 작동하는 닫기 아이콘이 표시됩니다."
L["Fonts, bar textures and sounds that other addons register with LibSharedMedia appear in the EllesmereUI menus, including ones registered after login."] = "다른 애드온이 LibSharedMedia에 등록한 글꼴, 바 텍스처, 소리가 로그인 후에 등록된 것까지 포함하여 EllesmereUI 메뉴에 나타납니다."
L["A shared outline picker for individual texts: None, Outline, Thick Outline or Shadow, with Module Default following the Fonts page. Text keeps its color when you switch."] = "개별 글자를 위한 공용 외곽선 선택기: 없음, 외곽선, 굵은 외곽선, 그림자이며, 모듈 기본값은 글꼴 페이지를 따릅니다. 전환해도 글자 색상은 유지됩니다."
L["The Incompatible Addon popup can disable the other addon or the affected EllesmereUI module and reload. Okay and Don't show again work as before."] = "호환되지 않는 애드온 팝업에서 다른 애드온이나 영향을 받는 EllesmereUI 모듈을 비활성화하고 재시작할 수 있습니다. 확인과 다시 표시 안 함은 이전처럼 작동합니다."
L["Per-spec setting groups with automatic capture and their own Unlock Mode layouts, plus conditional overrides for dungeons, raids, arenas, battlegrounds, solo play and out of combat."] = "자동 기록과 자체 잠금 해제 모드 레이아웃을 갖춘 전문화별 설정 그룹, 그리고 던전, 공격대, 투기장, 전장, 혼자 플레이, 전투 밖을 위한 조건부 재정의."
L["The Esc menu has EllesmereUI and EUI Unlock Mode buttons, shown by default. Both follow the EUI Buttons setting in Global Settings."] = "Esc 메뉴에 EllesmereUI와 EUI 잠금 해제 모드 버튼이 기본으로 표시됩니다. 두 버튼 모두 전체 설정의 EUI 버튼 설정을 따릅니다."
L["With Show Spell ID on Tooltip on, item tooltips add the item ID and icon file name. Each line has its own toggle"] = "툴팁에 주문 ID 표시를 켜면 아이템 툴팁에 아이템 ID와 아이콘 파일 이름이 추가됩니다. 각 줄마다 개별 토글이 있습니다"
L["Raid and Unit Frames read absorb shields from a shared estimate: rank base value plus your own spell power, minus what each shield absorbs in the combat log. Clients with a native absorb API use it directly"] = "공격대 프레임과 유닛 프레임은 공용 추정치에서 흡수 보호막을 읽습니다: 등급 기본값에 자신의 주문력을 더하고, 전투 기록에서 각 보호막이 흡수한 양을 뺍니다. 기본 흡수 API가 있는 클라이언트는 그것을 직접 사용합니다"
L["Arena Frames joins the sidebar, first-use list, profiles, spec overrides, module fonts and search"] = "투기장 프레임이 사이드바, 첫 사용 목록, 프로필, 전문화 재정의, 모듈 글꼴 및 검색에 추가됩니다"
L["Profile strings and shared exports work again"] = "프로필 문자열과 공유 내보내기가 다시 작동합니다"
L["An ice blue options theme; Match Accent to Theme follows each theme's palette"] = "얼음 파란색 설정 테마가 추가되었습니다. 강조 색상을 테마에 맞춤은 각 테마의 색상표를 따릅니다"
L["Lights, beams, music and spin on boss kills, arena and battleground wins, Bloodlust/Heroism and level ups"] = "우두머리 처치, 투기장 및 전장 승리, 피의 욕망/영웅심, 레벨 업 시 조명, 광선, 음악, 회전 효과"
L["Show Spell ID on Tooltip covers spells, action buttons, auras and chat links (off by default)"] = "툴팁에 주문 ID 표시가 주문, 행동 버튼, 오라, 대화 링크에 적용됩니다 (기본값 꺼짐)"
L["The options sidebar shows the combined memory used by all loaded EllesmereUI addons"] = "설정 사이드바에 불러온 모든 EllesmereUI 애드온이 사용하는 메모리 합계가 표시됩니다"
L["The sidebar sync button opens its profile list again instead of erroring when you have more than one profile."] = "프로필이 두 개 이상일 때 사이드바 동기화 버튼이 오류 대신 다시 프로필 목록을 엽니다."
L["Retail profile strings bring their element positions: action, XP and menu bars, CDM bars, raid and party frames, chat, damage meter windows, QoL displays, resource bars and the fixed tooltip land where the creator placed them."] = "리테일 프로필 문자열이 요소 위치를 가져옵니다: 행동, 경험치, 메뉴 바, CDM 바, 공격대 및 파티 프레임, 대화, 데미지 미터기 창, 편의 기능 표시, 자원 바, 고정 툴팁이 제작자가 배치한 위치에 놓입니다."
L["Nameplates-only Retail profile strings are recognised as Retail; bar width and height, cast bar height and color, name size and aura sizes carry over."] = "이름표 전용 리테일 프로필 문자열이 리테일로 인식되며, 바 너비와 높이, 시전 바 높이와 색상, 이름 크기, 오라 크기가 적용됩니다."
L["Unlock Mode: the top bar toggle icons and labels are brighter, so they no longer read dark grey on the banner."] = "잠금 해제 모드: 상단 바의 토글 아이콘과 라벨이 더 밝아져 배너 위에서 더 이상 어두운 회색으로 보이지 않습니다."
L["Set Focus and Clear Focus in right-click menus from EUI frames go through a secure button out of combat instead of being blocked; in combat they are hidden."] = "EUI 프레임의 우클릭 메뉴에 있는 주시 대상 지정과 주시 대상 해제가 전투 밖에서는 차단되지 않고 보안 버튼을 통해 실행됩니다. 전투 중에는 숨겨집니다."
L["Unlock Mode: the arrow keys move the selected element 1 pixel again (hold Shift for 100)."] = "잠금 해제 모드: 방향키로 선택한 요소를 다시 1픽셀씩 이동합니다 (Shift를 누르면 100)."
L["Works alongside !!!ClassicAPI: its clipping and mask functions are no longer used on EUI frames, so animated glows and the options panel stop erroring."] = "!!!ClassicAPI와 함께 작동합니다: 해당 애드온의 클리핑 및 마스크 함수가 더 이상 EUI 프레임에 사용되지 않아, 애니메이션 반짝임과 설정 창에서 오류가 나지 않습니다."
L["Opening the options no longer errors with \"attempt to index local 'mask'\" on clients where another addon adds an empty mask function."] = "다른 애드온이 빈 마스크 함수를 추가하는 클라이언트에서 설정을 열 때 더 이상 \"attempt to index local 'mask'\" 오류가 발생하지 않습니다."
L["The profile Import and Export boxes no longer error with \"attempt to call method 'GetNumLines'\" and scroll to fit long strings."] = "프로필 가져오기 및 내보내기 상자에서 더 이상 \"attempt to call method 'GetNumLines'\" 오류가 발생하지 않으며, 긴 문자열에 맞게 스크롤됩니다."
L["The collapsed menu shows the Ellesmere E logo again instead of a plain black circle."] = "접힌 메뉴에 단순한 검은 원 대신 Ellesmere E 로고가 다시 표시됩니다."
L["Action button tooltips show the real spell ID instead of the spellbook slot."] = "행동 버튼 툴팁에 주문책 칸 대신 실제 주문 ID가 표시됩니다."
L["Fixed an \"attempt to call global 'issecretvalue'\" error from Cooldown Manager glows before the options panel was first opened."] = "설정 창을 처음 열기 전에 재사용 대기시간 관리자 반짝임에서 발생하던 \"attempt to call global 'issecretvalue'\" 오류를 수정했습니다."
L["Unlock Mode widget tooltips use Wrath-compatible alpha fades, fixing the SetFromAlpha error on Grow Right."] = "잠금 해제 모드 위젯 툴팁이 리치 왕의 분노 호환 투명도 페이드를 사용하여 오른쪽 확장의 SetFromAlpha 오류를 수정했습니다."
L["The options search results list has a fully opaque background with its results drawn above it, so sidebar and page text no longer bleeds into the results."] = "설정 검색 결과 목록의 배경이 완전히 불투명해지고 결과가 그 위에 그려져, 사이드바와 페이지 글자가 더 이상 결과에 비치지 않습니다."
L["Unlock Mode no longer errors on SetMaxLines when it first opens, so element movers appear again."] = "잠금 해제 모드를 처음 열 때 더 이상 SetMaxLines 오류가 발생하지 않아 요소 이동 핸들이 다시 나타납니다."
L["The Patch Notes reminder dot now lights after each backport update."] = "패치 노트 알림 점이 이제 백포트 업데이트마다 켜집니다."
L["The options search results now draw above the sidebar and page instead of behind them."] = "설정 검색 결과가 이제 사이드바와 페이지 뒤가 아니라 위에 그려집니다."
L["The Unlock Mode right-click menu no longer closes right after opening when many elements are on screen."] = "화면에 요소가 많을 때 잠금 해제 모드 우클릭 메뉴가 열리자마자 닫히지 않습니다."
L["Opening the Raid Frames options no longer causes a stack overflow in Settings Overrides."] = "공격대 프레임 설정을 열 때 더 이상 설정 재정의에서 스택 오버플로가 발생하지 않습니다."
L["Unlock Mode art, options page icons and the Unlock Mode top bar are now visible and readable."] = "잠금 해제 모드 그림, 설정 페이지 아이콘, 잠금 해제 모드 상단 바가 이제 보이고 읽을 수 있습니다."
L["The addon list shows clean module names, grouped under EllesmereUI in addon managers."] = "애드온 목록에 깔끔한 모듈 이름이 표시되며, 애드온 관리자에서 EllesmereUI 아래에 묶입니다."
L["Search Features and Search Module Settings accept typing again."] = "기능 검색과 모듈 설정 검색에 다시 입력할 수 있습니다."
L["Clients whose atlas lookup errors on unknown names (such as custom 3.3.5 clients with Retail UI ports) no longer stop EllesmereUI files from loading."] = "알 수 없는 이름에 대해 아틀라스 조회 오류가 나는 클라이언트(리테일 UI를 이식한 사용자 지정 3.3.5 클라이언트 등)에서 더 이상 EllesmereUI 파일 로드가 중단되지 않습니다."
L["Like Retail 9.4, the DataBars page opens with a bar selector at the top: rename or delete a bar right in its menu, or pick + Create New DataBar. + New Bar shows the four starter templates as cards, and with no bars yet the page shows them as a card grid."] = "리테일 9.4처럼 데이터 바 페이지 상단에 바 선택기가 있습니다: 메뉴에서 바로 바 이름을 바꾸거나 삭제하거나, + Create New DataBar를 선택하세요. + New Bar는 네 가지 시작 템플릿을 카드로 보여주며, 바가 아직 없으면 페이지에 카드 격자로 표시됩니다."
L["Like Retail 9.4, the options window has a Window Scale slider in its top corner that resizes it in smooth 5% steps; the mouse wheel over it, or Shift + mouse wheel anywhere on the window, works too. The credit to Ellesmere now sits under the close button."] = "리테일 9.4처럼 설정 창 상단 모서리에 창 배율 슬라이더가 있어 5% 단위로 부드럽게 크기를 조절합니다. 그 위에서 마우스 휠을 돌리거나, 창 어디서든 Shift + 마우스 휠을 사용해도 됩니다. Ellesmere에 대한 크레딧은 이제 닫기 버튼 아래에 있습니다."
L["Global Settings opens with Reset ALL EUI Addon Settings and Uninstall EUI side by side, like Retail 9.4. Reset ALL now asks you to type Confirm. Optimize My FPS and Graphics is gone: the graphics settings it changed do not exist on this client."] = "전체 설정이 리테일 9.4처럼 모든 EUI 애드온 설정 초기화와 EUI 제거를 나란히 보여주며 열립니다. 모두 초기화는 이제 Confirm을 입력하도록 요청합니다. FPS 및 그래픽 최적화는 제거되었습니다: 이 기능이 바꾸던 그래픽 설정이 이 클라이언트에는 없습니다."
L["Like Retail 9.4, each look card on the Style page has a menu of the modules using it: tick modules under another look, then press Apply Styles to switch them all with one reload. The menus list only looks this client can draw: Cooldown Manager, Minimap and Damage Meters offer EllesmereUI and Classic WoW UI, Player Aura Bars is gone, and Apply to All skips modules without that look."] = "리테일 9.4처럼 모양 페이지의 각 모양 카드에 해당 모양을 사용하는 모듈 메뉴가 있습니다: 다른 모양을 쓰는 모듈을 체크한 다음 스타일 적용을 누르면 한 번의 재시작으로 모두 전환됩니다. 메뉴에는 이 클라이언트가 그릴 수 있는 모양만 표시됩니다: 재사용 대기시간 관리자, 미니맵, 데미지 미터기는 EllesmereUI와 클래식 WoW UI를 제공하고, 플레이어 오라 바는 제거되었으며, 모두 적용은 해당 모양이 없는 모듈을 건너뜁니다."
L["The import page can update your current profile instead of making a new one: tick Import into current profile and the string's selected modules (for example only Nameplates) replace their settings there while the rest of the profile stays."] = "가져오기 페이지에서 새 프로필을 만드는 대신 현재 프로필을 갱신할 수 있습니다: 현재 프로필로 가져오기를 체크하면 문자열에서 선택한 모듈(예: 이름표만)의 설정이 그 프로필에서 교체되고 나머지는 유지됩니다."
L["The EUI Staff page opens with thanks to Ellesmere and the port staff card with a GitHub link to the releases. The header line crediting Ellesmere opens it."] = "EUI 제작진 페이지가 Ellesmere에 대한 감사와 릴리스로 가는 GitHub 링크가 있는 포팅 제작진 카드로 열립니다. Ellesmere를 기리는 머리글 줄을 누르면 이 페이지가 열립니다."
L["Custom spell reminders, visibility and sounds are saved separately for each character, independently of shared profiles."] = "사용자 지정 주문 알림, 표시 여부, 소리가 공유 프로필과 별개로 캐릭터마다 따로 저장됩니다."
L["Optional achievement, trade and guild recruitment filters, plus your own blocked words and phrases."] = "선택적인 업적, 거래, 길드 모집 필터와 직접 지정한 차단 단어 및 문구."
L["Configure repeat timing, sender matching and chat scopes from the new Spam Filter page."] = "새 스팸 필터 페이지에서 반복 간격, 발신자 일치, 대화 범위를 설정합니다."
L["Outline menus in the Nameplates and Unit Frames text cogs, and Zone Text Outline in Quality of Life. The Unit Frames preview shows each text's outline."] = "이름표와 유닛 프레임 글자 톱니바퀴에 외곽선 메뉴가, 편의 기능에 지역 글자 외곽선이 추가되었습니다. 유닛 프레임 미리보기에 각 글자의 외곽선이 표시됩니다."
L["New PETS and DIMINISHING RETURNS sections, plus Fade Out of Range and its opacity under Target and Visibility."] = "새 소환수 및 점감 효과 섹션과, 대상 및 표시 여부 아래에 사거리 밖 흐리기 및 그 투명도가 추가되었습니다."
L["Announce Interrupts and Accept Invites from Friends & Guild in the GROUP section, and a Disband Group button on Raid Tools."] = "그룹 섹션에 차단 알림과 친구 및 길드 초대 수락이, 공격대 도구에 그룹 해체 버튼이 추가되었습니다."
L["Bar Display, Menu, Bags & XP Bars and Bar Animations, with a live preview of the selected bar. Click an icon, keybind or count to jump to its setting."] = "바 표시, 메뉴, 가방 & 경험치 바, 바 애니메이션과 선택한 바의 실시간 미리보기. 아이콘, 단축키, 개수를 클릭하면 해당 설정으로 이동합니다."
L["The Raid and Party pages gain the Retail DISPELS section and a Preview Mode (Real, Overlay or No Preview) at the top."] = "공격대 및 파티 페이지 상단에 리테일 해제 섹션과 미리보기 모드(실제, 오버레이, 미리보기 없음)가 추가되었습니다."
L["Party and Raid pages gain a TARGETED SPELLS section: mode, preview, icon size, maximum icons, position, growth, offsets, cast swipe, cast timer and interruptible colors."] = "파티 및 공격대 페이지에 대상 지정 주문 섹션이 추가되었습니다: 모드, 미리보기, 아이콘 크기, 최대 아이콘 수, 위치, 확장 방향, 오프셋, 시전 회전 효과, 시전 타이머, 차단 가능 색상."
L["Raid Frames (Party and Raid) and Unit Frames (player, target, focus) gain an ABSORBS section for the estimated shields, with a shield in the Unit Frames preview."] = "공격대 프레임(파티 및 공격대)과 유닛 프레임(플레이어, 대상, 주시 대상)에 추정 보호막을 위한 흡수 효과 섹션이 추가되었으며, 유닛 프레임 미리보기에 보호막이 표시됩니다."
L["CDM Bars now opens with Retail's bar dropdown (rename or delete custom bars, add Cooldowns, Utility, Buff or FocusKick bars) and the selected bar's icons: drag to reorder, click an icon to edit it, middle-click to remove it, and use + to add spells or buffs."] = "CDM 바가 이제 리테일의 바 드롭다운(사용자 지정 바 이름 변경 또는 삭제, 재사용 대기시간, 유틸리티, 강화 효과 또는 주시 차단 바 추가)과 선택한 바의 아이콘으로 열립니다: 끌어서 순서를 바꾸고, 아이콘을 클릭해 편집하고, 가운데 클릭으로 제거하며, +로 주문이나 강화 효과를 추가합니다."
L["Hide server announcements such as \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\", optionally keeping deaths from a chosen level up visible."] = "\"Name the level 11 Gnome Warrior has been slain by ... in Westfall\" 같은 서버 공지를 숨기며, 선택한 레벨 이상의 죽음은 선택적으로 계속 표시합니다."
L["The FocusKick Cast Sound and the Chat sounds list EllesmereUI and SharedMedia sounds, and the Textures page links Damage Meters to its per-window Bar Texture"] = "주시 차단 시전 소리와 대화 소리 목록에 EllesmereUI 및 SharedMedia 소리가 표시되며, 텍스처 페이지에서 데미지 미터기의 창별 바 텍스처로 연결됩니다"
L["New dropdown at the top of Icons, with a link to apply it to every bar. The preview shows the shape."] = "아이콘 상단의 새 드롭다운으로, 모든 바에 적용하는 링크가 있습니다. 미리보기에 모양이 표시됩니다."
L["Boss Debuff Icon, Icon Size, Icon Offset Y and Show Dispellable When No Boss Debuff under Dispels"] = "해제 아래의 우두머리 약화 효과 아이콘, 아이콘 크기, 아이콘 세로 위치, 우두머리 약화 효과가 없을 때 해제 가능 표시"
L["General, Layout, Health and Power, Text, Icons, Cast Bar and Target and Visibility sections"] = "일반, 배치, 생명력 및 자원, 글자, 아이콘, 시전 바, 대상 및 표시 여부 섹션"
L["Display, Extras and Wrath Inventory settings, including Delete Saved Character"] = "저장된 캐릭터 삭제를 포함한 표시, 추가 기능, 리치 왕의 분노 소지품 설정"
L["Class icon themes, class colored names, borders, accent colors, faction banners and invite auto-accept"] = "직업 아이콘 테마, 직업 색상 이름, 테두리, 강조 색상, 진영 배너 및 초대 자동 수락"
L["Display, Colors, General and Aura Filters with inline color swatches and cog menus"] = "인라인 색상 견본과 톱니바퀴 메뉴가 있는 표시, 색상, 일반, 오라 필터"
L["Quick Loot, Auto-Fill Delete Confirmation, Auto Repair and Auto Sell Junk in the Retail layout"] = "리테일 레이아웃의 빠른 전리품 획득, 삭제 확인 자동 입력, 자동 수리, 잡템 자동 판매"
L["Display, Colors and Extras sections with inline swatches and auto accept and turn-in cogs"] = "인라인 견본과 자동 수락 및 완료 톱니바퀴가 있는 표시, 색상, 추가 기능 섹션"
L["Wrath spell icons, real cast times and the same faction and portrait art as the live frames"] = "리치 왕의 분노 주문 아이콘, 실제 시전 시간, 실제 프레임과 같은 진영 및 초상화 그림"
L["The Active Profile dropdown shows the rename, delete and keybind icons on each profile again."] = "활성 프로필 드롭다운의 각 프로필에 이름 변경, 삭제, 단축키 아이콘이 다시 표시됩니다."
L["Dropdowns open again with !!!ClassicAPI installed; its clipping function no longer moves the menus into an empty scroll frame."] = "!!!ClassicAPI가 설치되어 있어도 드롭다운이 다시 열립니다. 해당 애드온의 클리핑 함수가 더 이상 메뉴를 빈 스크롤 프레임으로 옮기지 않습니다."
L["Resetting Global Settings no longer stops partway with an error and reloads the UI again."] = "전체 설정 초기화가 더 이상 오류로 중간에 멈추지 않고 다시 UI를 재시작합니다."
L["Options that do nothing on the Wrath client are hidden: image sharpening, Lag Tolerance, Combat Text Size, Swiftmend dim, Slug outline, class resource dark mode and colors, Retail-only class and power colors, and cursor ring textures."] = "리치 왕의 분노 클라이언트에서 아무 기능도 하지 않는 설정은 숨겨집니다: 이미지 선명화, 지연 허용치, 전투 글자 크기, 신속한 치유 흐림, Slug 외곽선, 직업 자원 어두운 모드 및 색상, 리테일 전용 직업 및 자원 색상, 커서 고리 텍스처."
L["Global Settings no longer shows the Gamepad page, which has nothing to control on the Wrath client."] = "전체 설정에 리치 왕의 분노 클라이언트에서 조작할 것이 없는 게임패드 페이지가 더 이상 표시되지 않습니다."
L["Max Camera Distance saves and keeps its value instead of resetting to 1.0, and goes up to 4 like the Wrath client allows."] = "최대 카메라 거리가 1.0으로 초기화되지 않고 값을 저장 및 유지하며, 리치 왕의 분노 클라이언트가 허용하는 4까지 올라갑니다."
L["CDM Bars and Tracking Bars open without an \"attempt to call field 'disabled'\" error, and nine toggles show their tooltips again."] = "CDM 바와 추적 바가 \"attempt to call field 'disabled'\" 오류 없이 열리며, 9개의 토글에 다시 툴팁이 표시됩니다."
L["Chat > Spam Filter: the chat type settings stay usable when only the trade or recruitment filter is on, and the tooltips explain what each one covers."] = "대화 > 스팸 필터: 거래 또는 모집 필터만 켜져 있어도 대화 유형 설정을 계속 사용할 수 있으며, 툴팁에서 각각 무엇을 다루는지 설명합니다."
L["Opening the options no longer makes later Blizzard actions risk being blocked in EllesmereUI's name."] = "설정을 열어도 이후의 블리자드 동작이 EllesmereUI 이름으로 차단될 위험이 더 이상 생기지 않습니다."
L["Checklist menus such as Visibility tick and untick their boxes as soon as they are clicked, even when the module's live update runs into a problem, instead of only after closing and reopening the menu."] = "표시 여부 같은 체크리스트 메뉴가 메뉴를 닫았다 다시 열어야 반영되던 문제 없이, 모듈의 실시간 갱신에 문제가 생겨도 클릭하는 즉시 체크/해제됩니다."
L["Dropdown lists, checklists and other option popups draw their items above their own background, on a solid background, instead of showing faded items with the page bleeding through."] = "드롭다운 목록, 체크리스트 및 기타 설정 팝업이 항목을 배경 위에 단색 배경으로 그려, 항목이 흐려지거나 페이지가 비쳐 보이지 않습니다."
L["The Style page now keeps the Unit Frames health colors per look, so switching between Classic WoW UI and the EllesmereUI look keeps each one's colors."] = "모양 페이지가 이제 유닛 프레임 생명력 색상을 모양별로 유지하므로, 클래식 WoW UI와 EllesmereUI 모양을 오가도 각자의 색상이 유지됩니다."
L["The Unit Frames preview and power color swatches show the original game power colors under Classic WoW UI."] = "클래식 WoW UI에서 유닛 프레임 미리보기와 자원 색상 견본이 원래 게임 자원 색상을 표시합니다."
L["Each Core Text Position row, Spell Name, Cast Timer and Friendly Names now has its own gear for the outline instead of hiding it in the size popup."] = "각 핵심 글자 위치 행, 주문 이름, 시전 시간, 아군 이름에 크기 팝업 안에 숨기는 대신 외곽선용 톱니바퀴가 따로 생겼습니다."
L["Pressing Esc to close Blizzard windows no longer shows \"EllesmereUIOptions has been blocked from an action\"."] = "Esc로 블리자드 창을 닫을 때 더 이상 \"EllesmereUIOptions has been blocked from an action\"이 표시되지 않습니다."
L["Combat damage, healing, periodic and pet damage toggles use Wrath's own combat text settings."] = "전투 피해, 치유, 주기적 효과, 소환수 피해 토글이 리치 왕의 분노 자체 전투 글자 설정을 사용합니다."
L["Hidden option widgets no longer take keyboard focus after other windows close with Escape."] = "다른 창을 Esc로 닫은 후 숨겨진 설정 위젯이 더 이상 키보드 포커스를 가져가지 않습니다."
L["Dragging or typing in a slider no longer errors."] = "슬라이더를 끌거나 값을 입력할 때 더 이상 오류가 발생하지 않습니다."
L["The settings panel opens on clients whose atlas lookup errors on unknown names, instead of failing with an 'NS' error."] = "알 수 없는 이름에 대해 아틀라스 조회 오류가 나는 클라이언트에서 'NS' 오류로 실패하지 않고 설정 창이 열립니다."
L["Displays has a ZONE TEXT section with Move Zone Text."] = "표시에 지역 이름 이동이 있는 지역 글자 섹션이 추가되었습니다."
L["Raid Tools no longer has a BOSS MOD BARS section: AbilityTimeline's Sources options hide DBM and BigWigs bars."] = "공격대 도구에 더 이상 우두머리 애드온 바 섹션이 없습니다: AbilityTimeline의 Sources 설정에서 DBM과 BigWigs 바를 숨깁니다."
L["The Retail raid panel: show it never, in raids, in any group or always, as a resizable Compact Band, one or two windows, or only one part. It can start as a small icon, opens and closes with a keybind even in combat, and has three pull timers, Convert and Disband. Reinvite removes everyone and invites them back to the same kind of group, and Convert to Party rebuilds a raid of five or fewer as a party the same way. Shift + Left Click a marker to place its world marker when the marker item is in your bags, or Shift + Left Click the clear icon to reset world markers. In a raid it only shows for the leader and assistants."] = "리테일 공격대 패널: 표시 안 함, 공격대에서, 모든 그룹에서, 항상 표시 중 선택하며, 크기 조절 가능한 압축 띠, 창 하나 또는 두 개, 또는 한 부분만으로 표시합니다. 작은 아이콘으로 시작할 수 있고, 전투 중에도 단축키로 열고 닫으며, 전투 준비 타이머 세 개와 전환 및 해체 기능이 있습니다. 재초대는 모두를 내보낸 뒤 같은 종류의 그룹으로 다시 초대하며, 파티로 전환은 5명 이하의 공격대를 같은 방식으로 파티로 다시 구성합니다. 징표 아이템이 가방에 있으면 징표를 Shift + 왼쪽 클릭하여 위치 표시기를 놓거나, 지우기 아이콘을 Shift + 왼쪽 클릭하여 위치 표시기를 초기화합니다. 공격대에서는 공격대장과 부공격대장에게만 표시됩니다."
L["One key casts Misdirection or Tricks of the Trade on your focus, the tank (typed name, Main Tank or tank role), your friendly target or your pet. An icon shows who it will go to, the buff timer and the cooldown. Bind it in Key Bindings."] = "키 하나로 주시 대상, 탱커(입력한 이름, 메인 탱커 또는 탱커 역할), 우호적 대상, 또는 소환수에게 눈속임이나 속임수 거래를 시전합니다. 아이콘에 누구에게 시전될지, 강화 효과 타이머, 재사용 대기시간이 표시됩니다. 단축키 설정에서 지정하세요."
L["Damage taken, healing, avoids and entering or leaving combat scroll above the player frame instead of Blizzard's combat text, with Straight, Fountain or Static animations, colors per type and a mover in Unlock Mode."] = "받은 피해, 치유, 회피, 전투 시작/종료가 블리자드 전투 글자 대신 플레이어 프레임 위로 흘러가며, 직선, 분수, 고정 애니메이션, 유형별 색상, 잠금 해제 모드 이동 핸들을 제공합니다."
L["Picks an NPC's only dialog option for you. Hold Shift to skip it; instances and NPCs with quests to take or turn in are left alone. Its cog can also skip past low level quests."] = "NPC의 대화 선택지가 하나뿐일 때 자동으로 선택합니다. Shift를 누르면 건너뛰며, 인스턴스와 받거나 완료할 퀘스트가 있는 NPC는 제외됩니다. 톱니바퀴에서 저레벨 퀘스트를 건너뛰도록 설정할 수도 있습니다."
L["An arrow next to the To box lists your alts on this realm and faction, guild members and the last names you mailed. Click a name to fill it in."] = "받는 사람 칸 옆의 화살표로 이 서버와 진영의 내 다른 캐릭터, 길드원, 최근 우편을 보낸 이름 목록을 표시합니다. 이름을 클릭하면 입력됩니다."
L["Pick None, Outline, Thick Outline or Shadow for the zone, sub-zone and PvP text shown when entering an area. Blizzard Default keeps the game's own font."] = "지역에 들어갈 때 표시되는 지역, 하위 지역, PvP 글자에 없음, 외곽선, 굵은 외곽선, 그림자 중 선택합니다. 블리자드 기본은 게임 자체 글꼴을 유지합니다."
L["Posts the spell you or your pet interrupted, with a spell link, to Say, Emote, Party or Raid. Party and Raid switch to the battleground channel inside battlegrounds."] = "자신이나 소환수가 차단한 주문을 주문 링크와 함께 일반, 감정 표현, 파티 또는 공격대에 알립니다. 전장에서는 파티와 공격대가 전장 채널로 바뀝니다."
L["Group invites from your friends list and guildmates are accepted automatically, unless you are already grouped or queued in the Dungeon Finder."] = "이미 그룹에 있거나 던전 찾기 대기 중이 아니라면 친구 목록과 길드원의 그룹 초대를 자동으로 수락합니다."
L["A Disband button on Raid Tools removes everyone from your raid or party after a confirmation. Leader only, never in combat."] = "공격대 도구의 해체 버튼은 확인 후 공격대 또는 파티에서 모두를 내보냅니다. 공격대장 전용이며 전투 중에는 사용할 수 없습니다."
L["Loots everything instantly even with Blizzard's Auto Loot off; hold Shift to see the loot window. Locked slots such as group rolls and master loot are skipped."] = "블리자드 자동 전리품 획득이 꺼져 있어도 모든 전리품을 즉시 획득합니다. Shift를 누르면 전리품 창이 표시됩니다. 그룹 주사위나 담당자 획득 같은 잠긴 칸은 건너뜁니다."
L["FPS and latency, secondary stats, durability warning, combat and death alerts, a crosshair and a new target distance text, all movable in Unlock Mode."] = "FPS와 지연 시간, 보조 능력치, 내구도 경고, 전투 및 죽음 알림, 십자선, 새로운 대상 거리 글자를 모두 잠금 해제 모드에서 이동할 수 있습니다."
L["The FPS counter's new default Text Color, Quality, turns FPS and each latency value green, yellow or red (60/30 fps, 100/250 ms). Custom and Class Color remain available."] = "FPS 표시의 새 기본 글자 색상인 품질은 FPS와 각 지연 시간 값을 녹색, 노란색, 빨간색으로 표시합니다 (60/30 fps, 100/250 ms). 사용자 지정과 직업 색상도 계속 사용할 수 있습니다."
L["Alert sounds from SharedMedia packs that load after Quality of Life play too"] = "편의 기능보다 나중에 불러오는 SharedMedia 묶음의 알림 소리도 재생됩니다"
L["An Open All button takes items and gold one letter at a time, skipping COD and GM mail"] = "모두 열기 버튼은 아이템과 골드를 편지 하나씩 가져오며, 착불 우편과 GM 우편은 건너뜁니다"
L["With Send Mail open, Shift-click a bag item to attach it and matching items"] = "우편 보내기 창이 열려 있을 때 가방 아이템을 Shift-클릭하면 그 아이템과 같은 아이템을 첨부합니다"
L["Opens lootable containers one at a time out of combat (off by default)"] = "전투 밖에서 전리품이 든 용기를 하나씩 엽니다 (기본값 꺼짐)"
L["A Train All button beside Train shows how many spells are available and the total cost"] = "훈련 옆의 모두 훈련 버튼에 배울 수 있는 주문 수와 총 비용이 표시됩니다"
L["Pull timer length, DBM/BigWigs broadcast and a chat countdown"] = "전투 준비 타이머 길이, DBM/BigWigs 알림 및 대화 초읽기"
L["Raid Tools keeps its size after importing a Retail profile."] = "리테일 프로필을 가져온 후에도 공격대 도구가 크기를 유지합니다."
L["Shift-click mail attach no longer replaces the bag item click handler, so bag clicks stay free of taint."] = "우편 Shift-클릭 첨부가 더 이상 가방 아이템 클릭 처리기를 교체하지 않으므로, 가방 클릭에 오염이 생기지 않습니다."
L["Hiding DBM and BigWigs bars while AbilityTimeline is active moved to AbilityTimeline itself, as on Retail: Hide DBM bars and Hide BigWigs bars on its Sources page. The Raid Tools option is gone."] = "AbilityTimeline이 활성화된 동안 DBM과 BigWigs 바를 숨기는 기능은 리테일처럼 AbilityTimeline 자체로 옮겨졌습니다: Sources 페이지의 Hide DBM bars와 Hide BigWigs bars. 공격대 도구 설정은 제거되었습니다."
L["Logging out, exiting, releasing spirit and other Blizzard confirmation popups no longer trigger the \"EllesmereUIQoL has been blocked from an action only available to the Blizzard UI\" message."] = "로그아웃, 게임 종료, 영혼 해방 및 기타 블리자드 확인 팝업에서 더 이상 \"EllesmereUIQoL has been blocked from an action only available to the Blizzard UI\" 메시지가 발생하지 않습니다."
L["The zone name no longer appears in the middle of the screen at small UI scales. It now sits fixed at the top (X 9 / Y 322 from screen center), with no Unlock Mode mover."] = "작은 UI 배율에서 지역 이름이 더 이상 화면 중앙에 나타나지 않습니다. 이제 상단에 고정되며 (화면 중앙에서 X 9 / Y 322), 잠금 해제 모드 이동 핸들은 없습니다."
L["Show Player Buffs puts the hovered player's buffs as icons beside the tooltip, with position, size, icons per row and offsets."] = "플레이어 강화 효과 표시는 마우스를 올린 플레이어의 강화 효과를 툴팁 옆에 아이콘으로 표시하며, 위치, 크기, 줄당 아이콘 수, 오프셋을 설정할 수 있습니다."
L["Hovering a stat in the character sheet sidebar glows the equipped items that give it."] = "캐릭터 정보 창 사이드바의 능력치에 마우스를 올리면 그 능력치를 주는 착용 아이템이 빛납니다."
L["Inspect Enchants and Missing Enhancements"] = "살펴보기 마법부여 및 누락된 강화"
L["Inspect enchants show as an icon with the name on hover, or as names tinted by item quality, in their own size. At max level, red badges flag missing enchants, empty sockets and a missing belt buckle, as on your character sheet."] = "살펴보기 마법부여는 마우스를 올리면 이름이 나오는 아이콘으로, 또는 아이템 품질 색으로 물든 이름으로 별도 크기로 표시됩니다. 최고 레벨에서는 내 캐릭터 정보 창처럼 누락된 마법부여, 빈 보석 홈, 누락된 허리띠 버클을 빨간 배지로 표시합니다."
L["Saving an equipment set rebuilds the native icon picker even when already open, preventing the PaperDollFrame nil comparison error."] = "장비 구성을 저장하면 이미 열려 있어도 기본 아이콘 선택기를 다시 만들어 PaperDollFrame nil 비교 오류를 방지합니다."
L["Need, Greed, Disenchant and Pass buttons on loot rolls count what the rest of the group picked. Hover a button to see who, in class colors."] = "전리품 주사위의 입찰, 차비, 마력 추출, 포기 버튼에 나머지 그룹원이 선택한 수가 표시됩니다. 버튼에 마우스를 올리면 누가 선택했는지 직업 색상으로 보여줍니다."
L["Player tooltips show GearScore in the GearScoreLite colors, using its formula when it is loaded. GearScoreLite's own line is kept when its option is on."] = "플레이어 툴팁에 GearScoreLite 색상으로 GearScore가 표시되며, GearScoreLite가 로드되어 있으면 그 공식을 사용합니다. GearScoreLite 자체 줄은 해당 설정이 켜져 있으면 유지됩니다."
L["Enchants and gems on every slot, lowest durability, model rotate, pan and zoom, reorderable stat sections and a socket strip that fills sockets from your bags."] = "모든 칸의 마법부여와 보석, 최저 내구도, 모델 회전, 이동, 확대/축소, 순서를 바꿀 수 있는 능력치 섹션, 가방의 보석으로 보석 홈을 채우는 보석 홈 띠."
L["Class colored names and health bar, guild rank, target, item level and a cursor or fixed anchor"] = "직업 색상 이름과 생명력 바, 길드 등급, 대상, 아이템 레벨, 커서 또는 고정 기준점"
L["Item levels on inspect, docking beside the character window and a merchant list mode"] = "살펴보기의 아이템 레벨, 캐릭터 창 옆 도킹 및 상인 목록 모드"
L["Resurrect accept glow and a Dungeon Ready countdown bar"] = "부활 수락 반짝임과 던전 입장 준비 초읽기 바"
L["The server's Collections and Wardrobe & Transmog windows join the window skins"] = "서버의 수집품 및 형상변환 창이 창 스킨에 추가됩니다"
L["Barber Shop, PvP and battlemasters, Arena Registrar, battleground score, minimap and capture bar, Help and GM tickets, GM chat status, breath and fatigue timers, stopwatch, raid pullouts, debug tools and Ace3 config windows"] = "미용실, PvP 및 전투 지휘관, 투기장 등록관, 전장 점수, 미니맵 및 점령 바, 도움말 및 GM 문의, GM 대화 상태, 호흡 및 피로 타이머, 초시계, 공격대 분리 창, 디버그 도구, Ace3 설정 창"
L["Ready checks no longer leave an empty black panel for the leader or after you answer."] = "준비 확인이 더 이상 공격대장에게나 응답 후에 빈 검은 패널을 남기지 않습니다."
L["The character sheet Titles tab lists your known titles again; click one to wear it."] = "캐릭터 정보 창의 칭호 탭에 알고 있는 칭호가 다시 표시됩니다. 클릭하면 착용합니다."
L["The Guild Message Of The Day popup (and other wide text popups) no longer covers its title and buttons with the input box."] = "길드 오늘의 메시지 팝업(및 기타 넓은 글자 팝업)의 입력 상자가 더 이상 제목과 버튼을 가리지 않습니다."
L["The Achievements window no longer darkens the achievement list behind its border."] = "업적 창이 더 이상 테두리 뒤의 업적 목록을 어둡게 하지 않습니다."
L["The AddOn List window skin toggle only shows when the client has an AddOn List window."] = "애드온 목록 창 스킨 토글은 클라이언트에 애드온 목록 창이 있을 때만 표시됩니다."
L["Send Mail shows the To, Subject and message boxes again, and the typing cursor stays visible in skinned edit boxes."] = "우편 보내기에 받는 사람, 제목, 내용 상자가 다시 표시되며, 스킨이 적용된 입력 상자에서 입력 커서가 계속 보입니다."
L["The fixed tooltip anchor no longer snaps back to its saved spot while you drag it in Unlock Mode."] = "잠금 해제 모드에서 끄는 동안 고정 툴팁 기준점이 더 이상 저장된 위치로 되돌아가지 않습니다."
L["Auction House: panels and tabs added by Auctionator and other auction addons keep their own look and layout, and the footer Close buttons no longer get an \"x\" over their text."] = "경매장: Auctionator 및 기타 경매 애드온이 추가한 패널과 탭이 자체 모양과 배치를 유지하며, 하단 닫기 버튼 글자 위에 더 이상 \"x\"가 생기지 않습니다."
L["Talents: the close button and the points footer end at the scroll bar instead of past the window edge."] = "특성: 닫기 버튼과 포인트 하단이 창 가장자리를 넘지 않고 스크롤 바에서 끝납니다."
L["Window tabs keep their dark background instead of showing through."] = "창 탭이 비쳐 보이지 않고 어두운 배경을 유지합니다."
L["World map: the player arrow, party and raid dots, corpse and quest markers stay on the map art after a map view change during combat, including instance maps."] = "세계 지도: 전투 중 지도 보기가 바뀐 후에도 플레이어 화살표, 파티 및 공격대 점, 시체, 퀘스트 표시가 인스턴스 지도를 포함하여 지도 그림 위에 유지됩니다."
L["Native dropdown menus no longer show an empty square at the right of each row."] = "기본 드롭다운 메뉴의 각 행 오른쪽에 더 이상 빈 사각형이 표시되지 않습니다."
L["Dropdown boxes in Blizzard windows, such as the Dungeon Finder type, end at their arrow instead of past the window edge."] = "던전 찾기 유형 같은 블리자드 창의 드롭다운 상자가 창 가장자리를 넘지 않고 화살표에서 끝납니다."
L["Raid Information: the background covers the whole window, including the title, close button, last row and the Extend Raid Lock and Close buttons."] = "공격대 정보: 배경이 제목, 닫기 버튼, 마지막 행, 공격대 귀속 연장 및 닫기 버튼을 포함한 창 전체를 덮습니다."
L["The Talents and Glyphs background now ends above the tabs and beside the dual spec tabs."] = "특성 및 문양 배경이 이제 탭 위와 이중 특성 탭 옆에서 끝납니다."
L["The Glyphs tab shows its native parchment background again, aligned with the glyph sockets."] = "문양 탭에 기본 양피지 배경이 문양 홈에 맞춰 다시 표시됩니다."
L["Sliders in Blizzard windows, such as the Camera and Mouse options, are back to their normal size."] = "카메라 및 마우스 설정 같은 블리자드 창의 슬라이더가 원래 크기로 돌아왔습니다."
L["Hide Until Usable and Hide Outside Form/Stance"] = "사용 가능할 때까지 숨기기 및 변신/태세 밖에서 숨기기"
L["New Cooldown States: Hide Until Usable shows a spell only while it can be cast and is off cooldown (Overpower, Revenge, Victory Rush, Execute); low resources do not hide it. Hide Outside Form/Stance shows it only in the form or stance it needs. Both can close the gap or keep the place."] = "새 재사용 대기시간 상태: 사용 가능할 때까지 숨기기는 주문을 시전할 수 있고 재사용 대기 중이 아닐 때만 표시하며(제압, 복수, 연전연승, 마무리 일격), 자원 부족으로는 숨기지 않습니다. 변신/태세 밖에서 숨기기는 필요한 변신이나 태세일 때만 표시합니다. 둘 다 빈자리를 메우거나 자리를 유지할 수 있습니다."
L["The + menu adds an Empty Slot that keeps a position free on the bar, to group icons."] = "+ 메뉴로 바에서 위치를 비워 두는 빈 칸을 추가하여 아이콘을 묶을 수 있습니다."
L["Bars can switch to a Shaped swipe that follows round icons and takes a Swipe Color, instead of the client's dark square sweep."] = "바가 클라이언트의 어두운 사각형 회전 효과 대신 둥근 아이콘을 따르고 회전 효과 색상을 사용하는 모양 회전 효과로 전환할 수 있습니다."
L["Cooldowns, Utility and Buffs bars plus custom bars and a FocusKick bar, tracked from your spellbook, cooldowns and auras. Lists are saved per talent group."] = "재사용 대기시간, 유틸리티, 강화 효과 바와 사용자 지정 바 및 주시 차단 바로, 주문책, 재사용 대기시간, 오라에서 추적합니다. 목록은 특성 그룹별로 저장됩니다."
L["Aura or cooldown bars for player, target, focus or pet with textures, gradients, stack ticks and pandemic glow, arranged in groups."] = "플레이어, 대상, 주시 대상, 소환수의 오라 또는 재사용 대기시간 바로, 텍스처, 그라데이션, 중첩 눈금, 팬데믹 반짝임을 지원하며 그룹으로 배치됩니다."
L["The + buttons above the bar icons open Retail's add menu: custom spell, item or slot, trinkets, racial, potions and your learned spells, or buffs and buff presets from the gold +"] = "바 아이콘 위의 + 버튼은 리테일의 추가 메뉴를 엽니다: 사용자 지정 주문, 아이템 또는 칸, 장신구, 종족 특성, 물약, 배운 주문, 또는 금색 +에서 강화 효과와 강화 효과 프리셋"
L["Passive proc trinkets in the trinket slots show their icon and the internal cooldown after each proc, with the proc buff while it lasts"] = "장신구 칸의 지속 효과 발동 장신구는 아이콘과 각 발동 후 내부 재사용 대기시간을 표시하며, 발동 강화 효과가 지속되는 동안 함께 표시합니다"
L["Tracking bar textures include SharedMedia, and the FocusKick Cast Sound adds EllesmereUI and SharedMedia sounds to the Blizzard ones"] = "추적 바 텍스처에 SharedMedia가 포함되며, 주시 차단 시전 소리에 블리자드 소리 외에 EllesmereUI 및 SharedMedia 소리가 추가됩니다"
L["Light up EllesmereUI, Blizzard or ElvUI action buttons while an aura is active or missing"] = "오라가 활성화되어 있거나 없는 동안 EllesmereUI, 블리자드 또는 ElvUI 행동 버튼을 빛나게 합니다"
L["Always show, dim, hide on cooldown or when ready, and glow when ready"] = "항상 표시, 흐리게, 재사용 대기 중 또는 준비되면 숨기기, 준비되면 반짝임"
L["Racials, healthstones, Wrath potions and buffs such as Heroism and Bloodlust"] = "종족 특성, 생명석, 리치 왕의 분노 물약, 영웅심과 피의 욕망 같은 강화 효과"
L["Show an entry only when a chosen talent is learned"] = "선택한 특성을 배웠을 때만 항목을 표시합니다"
L["Utility bar options no longer switch to Buffs after a click, and the Cooldowns bar is no longer replaced by a second Buffs bar."] = "유틸리티 바 설정이 클릭 후 더 이상 강화 효과로 바뀌지 않으며, 재사용 대기시간 바가 더 이상 두 번째 강화 효과 바로 대체되지 않습니다."
L["Racials show once: the Utility bar no longer lists Arcane Torrent (and other racials with class variants) three times."] = "종족 특성이 한 번만 표시됩니다: 유틸리티 바에 비전 격류(및 직업별 변형이 있는 다른 종족 특성)가 더 이상 세 번 표시되지 않습니다."
L["A passive trinket in a trinket slot shows its own icon in the options instead of a question mark."] = "장신구 칸의 지속 효과 장신구가 설정에서 물음표 대신 자체 아이콘을 표시합니다."
L["Bars saved twice or under another bar's name (two Buffs bars and no Cooldowns) are repaired, so each built-in bar keeps its own icons and options."] = "두 번 저장되었거나 다른 바의 이름으로 저장된 바(강화 효과 바 두 개에 재사용 대기시간 바 없음)가 복구되어, 각 기본 바가 자체 아이콘과 설정을 유지합니다."
L["Auto Sized and Even Split bars with Retail backgrounds, borders and screen edge snapping, plus per-block margins, alignment, scale and colors."] = "리테일 배경, 테두리, 화면 가장자리 맞춤을 갖춘 자동 크기 및 균등 분할 바와 블록별 여백, 정렬, 배율, 색상."
L["20 Wrath Blocks"] = "리치 왕의 분노 블록 20개"
L["Clock, FPS, latency, location, gold history, bags, durability, XP and reputation, dual spec, professions, travel, micro menu, currency and more."] = "시계, FPS, 지연 시간, 위치, 골드 기록, 가방, 내구도, 경험치와 평판, 이중 특성, 전문 기술, 이동, 마이크로 메뉴, 화폐 등."
L["Latency text is green, yellow or red by connection quality by default. A Latency swatch in Text Color switches back to it after picking another color."] = "지연 시간 글자는 기본적으로 연결 품질에 따라 녹색, 노란색, 빨간색으로 표시됩니다. 다른 색상을 고른 후 글자 색상의 지연 시간 견본을 누르면 다시 돌아갑니다."
L["Column tooltips with clickable rows and secure spell, item and macro lines"] = "클릭할 수 있는 행과 보안 주문, 아이템, 매크로 줄이 있는 열 툴팁"
L["Every bar has a mover whose Element Options opens that bar's settings"] = "모든 바에 이동 핸들이 있으며, 요소 설정을 누르면 해당 바의 설정이 열립니다"
L["Profiles from 0.2 are converted automatically"] = "0.2 버전의 프로필은 자동으로 변환됩니다"
L["Bars snapped to a screen edge or set to full length start in their place after login instead of needing Unlock Mode opened and closed."] = "화면 가장자리에 맞춰졌거나 전체 길이로 설정된 바가 로그인 후 잠금 해제 모드를 열고 닫지 않아도 제자리에서 시작합니다."
L["The cast bar latency zone works for queued spells and remains visible during channels, with configurable color and millisecond text."] = "시전 바 지연 구간이 대기열 주문에도 작동하고 정신 집중 중에도 계속 표시되며, 색상과 밀리초 글자를 설정할 수 있습니다."
L["Class, Power and Health Bars, Cast Bar, GCD Bar, Swing Timer and Totem Bar, each element with its own Unlock Mode mover. Older profiles migrate once."] = "직업, 자원, 생명력 바, 시전 바, 글쿨 바, 자동 공격 타이머, 토템 바로, 각 요소마다 잠금 해제 모드 이동 핸들이 있습니다. 이전 프로필은 한 번 이전됩니다."
L["Main hand, off hand and ranged swings from the combat log, with queued Heroic Strike, Cleave and Maul, parry haste and speed changes."] = "전투 기록 기반의 주무기, 보조무기, 원거리 자동 공격으로, 대기열에 넣은 영웅의 일격, 회전베기, 후려치기, 무기 막기 가속, 속도 변화를 반영합니다."
L["Bar textures include textures from SharedMedia and other addons"] = "바 텍스처에 SharedMedia 및 다른 애드온의 텍스처가 포함됩니다"
L["Vertical bars, Retail texts, gradients, thresholds, tick marks and smoothing"] = "세로 바, 리테일 글자, 그라데이션, 임계값, 눈금 표시 및 부드러운 변화"
L["Death Knight rune order and countdowns, combo points, or Blizzard's own art"] = "죽음의 기사 룬 순서와 초읽기, 연계 점수, 또는 블리자드 자체 그림"
L["Channel ticks, latency, total duration and uninterruptible colors"] = "정신 집중 틱, 지연 시간, 총 지속 시간, 차단 불가 색상"
L["Totem icons and timers, and a movable Call Totem Bar"] = "토템 아이콘과 타이머, 이동 가능한 토템 소환 바"
L["The Call Totem Bar no longer resizes or moves during combat; changes apply when combat ends."] = "토템 소환 바가 더 이상 전투 중에 크기가 바뀌거나 이동하지 않으며, 변경 사항은 전투가 끝나면 적용됩니다."
L["The player cast bar shows the channeled spell's name instead of \"Channeling\"."] = "플레이어 시전 바에 \"Channeling\" 대신 정신 집중 주문 이름이 표시됩니다."
L["Class icons in the EUI themes, status orbs, notes in the details line, faction banners and hover highlight, with borders and accent colors."] = "EUI 테마의 직업 아이콘, 상태 구슬, 세부 줄의 쪽지, 진영 배너, 마우스 오버 강조와 테두리 및 강조 색상."
L["Accepts group invites from friends, and optionally from guild members, and closes the popup."] = "친구, 그리고 선택적으로 길드원의 그룹 초대를 수락하고 팝업을 닫습니다."
L["The window stays native but rows still get class icons and colored names"] = "창은 기본 모양을 유지하지만 행에는 직업 아이콘과 색상 이름이 적용됩니다"
L["Auto Accept picks quests from NPC dialogs, with Prevent Multi Quest Accept, and Auto Turn In completes single-reward quests. Hold Shift to skip."] = "자동 수락은 NPC 대화에서 퀘스트를 받으며 다중 퀘스트 수락 방지가 있고, 자동 완료는 보상이 하나인 퀘스트를 완료합니다. Shift를 누르면 건너뜁니다."
L["Uses the item of your tracked quest, found in the quest log, and only holds the key while there is an item to use."] = "퀘스트 목록에서 찾은 추적 중인 퀘스트의 아이템을 사용하며, 사용할 아이템이 있을 때만 키를 차지합니다."
L["The top line uses the accent color and Line Color tints the header divider"] = "상단 줄은 강조 색상을 사용하고 선 색상이 머리글 구분선에 색을 입힙니다"
L["/eqt show, /eqt hide and /eqt toggle"] = "/eqt show, /eqt hide 및 /eqt toggle"
L["Clear your focus by clicking the focus frame (Shift + Right Click by default, or Ctrl/Alt + Right Click, Middle Click, Shift + Left Click). Set it on the Focus frame page. Works in combat."] = "주시 대상 프레임을 클릭하여 주시 대상을 해제합니다 (기본값 Shift + 오른쪽 클릭, 또는 Ctrl/Alt + 오른쪽 클릭, 가운데 클릭, Shift + 왼쪽 클릭). 주시 대상 프레임 페이지에서 설정합니다. 전투 중에도 작동합니다."
L["Two new debuff filter modes: Raid Debuffs shows the common raid debuffs from anyone (armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements and Hunter's Mark), and Own and Raid Debuffs adds yours."] = "새 약화 효과 필터 모드 두 가지: 공격대 약화 효과는 누가 걸었든 일반적인 공격대 약화 효과(방어도, 받는 주문 및 물리 피해, 받는 치명타, 전투력, 공격 및 시전 속도, 받는 치유량, 심판, 사냥꾼의 징표)를 표시하고, 내 약화 효과 및 공격대 약화 효과는 내 것을 추가합니다."
L["Type Icon Position puts the icon of the player's highest dispellable debuff type on a point of the health bar, with its size and offsets in the cog. Only Dispellable by You now sits beside it and narrows the overlay, icon and border colors alike."] = "유형 아이콘 위치는 플레이어의 가장 높은 해제 가능 약화 효과 유형 아이콘을 생명력 바의 한 지점에 놓으며, 크기와 오프셋은 톱니바퀴에서 설정합니다. 내가 해제 가능한 것만이 이제 그 옆에 있으며 오버레이, 아이콘, 테두리 색상을 모두 좁힙니다."
L["The focus frame gets the aura Border Style, size and color settings, as player and target have."] = "주시 대상 프레임에 플레이어와 대상처럼 오라 테두리 모양, 크기, 색상 설정이 생겼습니다."
L["Player, target and focus show incoming heals past the health fill: yours and other players' in their own colors, from LibHealComm-4.0 (only healers running a HealComm addon are seen)."] = "플레이어, 대상, 주시 대상이 생명력 채우기 너머로 받을 치유를 표시합니다: 내 치유와 다른 플레이어의 치유를 각각의 색상으로 LibHealComm-4.0에서 가져옵니다 (HealComm 애드온을 사용하는 힐러만 보입니다)."
L["The debuff filters can now show or hide Sated, Exhaustion and the other Bloodlust lockout debuffs. They stay hidden by default."] = "약화 효과 필터에서 이제 만족함, 탈진 및 기타 피의 욕망 잠금 약화 효과를 표시하거나 숨길 수 있습니다. 기본값은 숨김입니다."
L["Left, Right, Center and Extra Text, the Bottom Text Bar texts and Power Percent each have an Outline choice under Size: None, Outline, Thick Outline or Shadow, or the module default."] = "왼쪽, 오른쪽, 중앙, 추가 글자, 하단 글자 바 글자, 자원 백분율 각각에 크기 아래 외곽선 선택이 있습니다: 없음, 외곽선, 굵은 외곽선, 그림자, 또는 모듈 기본값."
L["Anchor, growth, icons per row, duration and stack text, textured borders and dispel rings. Target and focus get Purgeable Buff Glow."] = "기준점, 확장 방향, 줄당 아이콘 수, 지속 시간 및 중첩 글자, 텍스처 테두리, 해제 고리. 대상과 주시 대상에 정화 가능 강화 효과 반짝임이 추가됩니다."
L["Every combat indicator style now shows, and highlighted portraits fit their shape instead of overflowing it."] = "모든 전투 표시기 스타일이 이제 표시되며, 강조된 초상화가 넘치지 않고 모양에 맞춰집니다."
L["Player, target, focus and boss health bars show estimated damage shields with Retail's Absorb Style, Opacity, Color, Placement, Show Overshield and Show on Boss Frames"] = "플레이어, 대상, 주시 대상, 우두머리 생명력 바에 리테일의 흡수 모양, 투명도, 색상, 배치, 초과 보호막 표시, 우두머리 프레임에 표시로 추정 피해 보호막이 표시됩니다"
L["Mana or Mana + Form Power, with a separate form bar"] = "마나 또는 마나 + 변신 자원, 별도의 변신 바 포함"
L["Threat %, a pet power bar and the pet happiness icon"] = "위협 수준 %, 소환수 자원 바, 소환수 행복도 아이콘"
L["Pooled aura indicators on the health bar with Use Indicator Layout"] = "표시기 레이아웃 사용으로 생명력 바에 모은 오라 표시기"
L["Fill, full, gradient and sharp gradient overlays in the dispel color"] = "해제 색상의 채우기, 전체, 그라데이션, 선명한 그라데이션 오버레이"
L["Under Classic WoW UI and Blizzard Style, the leader crown sits on the portrait's top corner, as on the original frames, instead of inside the health bar."] = "클래식 WoW UI와 블리자드 스타일에서 지휘관 왕관이 생명력 바 안이 아니라 원래 프레임처럼 초상화 위쪽 모서리에 놓입니다."
L["The party leader icon on unit frames shows on the leader only instead of on several party members."] = "유닛 프레임의 파티장 아이콘이 여러 파티원이 아닌 파티장에게만 표시됩니다."
L["Set Focus and Clear Focus in the unit frame right-click menu work out of combat without the 'blocked from an action' popup; in combat they are hidden."] = "유닛 프레임 우클릭 메뉴의 주시 대상 지정과 주시 대상 해제가 전투 밖에서 '동작이 차단되었습니다' 팝업 없이 작동합니다. 전투 중에는 숨겨집니다."
L["Unit frame bars and portraits no longer get moved into scroll frames when !!!ClassicAPI is installed."] = "!!!ClassicAPI가 설치되어 있어도 유닛 프레임 바와 초상화가 더 이상 스크롤 프레임으로 옮겨지지 않습니다."
L["Important Cast Glow is hidden for target and focus cast bars; the Wrath client cannot tell which spells are important."] = "대상과 주시 대상 시전 바에서 중요한 시전 반짝임이 숨겨집니다. 리치 왕의 분노 클라이언트는 어떤 주문이 중요한지 알 수 없습니다."
L["Channel cast bars show the spell's name instead of \"Channeling\"."] = "정신 집중 시전 바에 \"Channeling\" 대신 주문 이름이 표시됩니다."
L["Boss frames now update health, power and text while the boss is not your target or focus."] = "우두머리 프레임이 이제 우두머리가 대상이나 주시 대상이 아니어도 생명력, 자원, 글자를 갱신합니다."
L["Visibility conditions (combat, group, and hiding without a target) now apply to the frames instead of stopping with an error, so the Visibility menu's boxes also tick right away."] = "표시 여부 조건(전투, 그룹, 대상 없을 때 숨기기)이 이제 오류로 멈추지 않고 프레임에 적용되므로, 표시 여부 메뉴의 체크 상자도 바로 체크됩니다."
L["Classic WoW UI power bars now stay inside the frame art: the art's rim draws over the power bar as it does over the health bar."] = "클래식 WoW UI 자원 바가 이제 프레임 그림 안에 머뭅니다: 생명력 바와 마찬가지로 그림의 테두리가 자원 바 위에 그려집니다."
L["Classic WoW UI now gives every unit frame the original green health bar instead of class colors. Returning to the EllesmereUI look restores your colors."] = "클래식 WoW UI는 이제 모든 유닛 프레임에 직업 색상 대신 원래의 녹색 생명력 바를 사용합니다. EllesmereUI 모양으로 돌아가면 색상이 복원됩니다."
L["Classic WoW UI power bars use the original game colors (deep blue mana, red rage, yellow energy) instead of the EllesmereUI palette. Other looks keep the palette."] = "클래식 WoW UI 자원 바가 EllesmereUI 색상표 대신 원래 게임 색상(진한 파란색 마나, 빨간색 분노, 노란색 기력)을 사용합니다. 다른 모양은 색상표를 유지합니다."
L["Text outlines now apply to the live frames, not only the options preview."] = "글자 외곽선이 이제 설정 미리보기뿐 아니라 실제 프레임에도 적용됩니다."
L["Unit frames no longer fail to load on setups whose mask textures come back empty (absorb bar error at login)."] = "마스크 텍스처가 비어 있는 환경에서도 유닛 프레임이 정상적으로 불러와집니다 (로그인 시 흡수 바 오류)."
L["Icons shown by spell ID now show the right icon or a question mark, never an empty square."] = "주문 ID로 표시되는 아이콘이 이제 올바른 아이콘이나 물음표를 표시하며, 빈 사각형은 표시하지 않습니다."
L["The faction indicator no longer errors in mercenary mode, and Retail-only PvP styles use the Wrath PvP icon."] = "진영 표시기가 용병 모드에서 더 이상 오류를 일으키지 않으며, 리테일 전용 PvP 스타일은 리치 왕의 분노 PvP 아이콘을 사용합니다."
L["Level text no longer errors with Font not set when frames are first created."] = "프레임이 처음 만들어질 때 레벨 글자에서 더 이상 Font not set 오류가 발생하지 않습니다."
L["Like Retail 9.4, the Experience Bar section opens with XP Bar Style: EllesmereUI for the EUI bar, Luxthos for the EUI bar in the Luxthos WeakAura layout, or Blizz Default for Blizzard's own XP and reputation bars. It replaces Enable Experience Bar and the Apply Luxthos Layout button."] = "리테일 9.4처럼 경험치 바 섹션이 경험치 바 스타일로 시작합니다: EUI 바는 EllesmereUI, Luxthos WeakAura 배치의 EUI 바는 Luxthos, 블리자드 자체 경험치 및 평판 바는 블리자드 기본. 경험치 바 활성화와 Luxthos 배치 적용 버튼을 대체합니다."
L["Like Retail 9.4, any horizontal bar can show the classic gryphons at its left end, right end or both, from the End Caps menu at the end of LAYOUT. The cog sets their size and offsets, and Apply to All copies them to every bar. The live preview shows them too."] = "리테일 9.4처럼 모든 가로 바에서 배치 끝부분의 끝 장식 메뉴를 통해 왼쪽 끝, 오른쪽 끝 또는 양쪽에 클래식 그리핀을 표시할 수 있습니다. 톱니바퀴에서 크기와 오프셋을 설정하고, 모두 적용으로 모든 바에 복사합니다. 실시간 미리보기에도 표시됩니다."
L["The XP bar gets Retail's Quest XP Overlay (completed quests in green, incomplete in gold), dividers with Smart Ticks, gradient fills, background and rested colors, and seven text positions showing values, completed quest XP, XP per hour, time to level and time played. Apply Luxthos Layout recreates the popular Luxthos XP bar WeakAura, with Show at Max Level, a spark and rested XP after quest XP."] = "경험치 바에 리테일의 퀘스트 경험치 오버레이(완료한 퀘스트는 녹색, 미완료는 금색), 스마트 눈금 구분선, 그라데이션 채우기, 배경 및 휴식 색상, 그리고 수치, 완료한 퀘스트 경험치, 시간당 경험치, 레벨업까지 남은 시간, 플레이 시간을 보여주는 7개의 글자 위치가 추가됩니다. Luxthos 배치 적용은 인기 있는 Luxthos 경험치 바 WeakAura를 최고 레벨에서 표시, 반짝이, 퀘스트 경험치 이후 휴식 경험치와 함께 재현합니다."
L["Buttons holding an equipped item, such as a trinket, can show a border in its rarity color. Off by default."] = "장신구처럼 착용한 아이템이 들어 있는 버튼에 희귀도 색상 테두리를 표시할 수 있습니다. 기본값 꺼짐."
L["Four extra bars, off by default, each with its own keybinds, Unlock Mode mover and the full Bar Display settings. Warriors, Druids, Rogues and Priests see which stance or form shares a bar's slots."] = "기본값으로 꺼져 있는 추가 바 네 개로, 각각 자체 단축키, 잠금 해제 모드 이동 핸들, 전체 바 표시 설정을 가집니다. 전사, 드루이드, 도적, 사제는 어떤 태세나 변신이 바의 칸을 공유하는지 볼 수 있습니다."
L["Circle and Portrait draw round icons, Diamond, Hexagon and Shield crop the icon to the shape, and Square and Curved Square add a shaped outline. Set per bar, including pet and stance."] = "원과 초상화는 둥근 아이콘을 그리고, 다이아몬드, 육각형, 보호막은 아이콘을 모양에 맞게 자르며, 사각형과 둥근 사각형은 모양 외곽선을 추가합니다. 소환수와 태세 바를 포함하여 바별로 설정합니다."
L["Type /kb, hover a button and press a key to bind it, including modifiers, mouse buttons and the wheel. Right-click clears; Cancel or Esc undoes."] = "/kb를 입력하고 버튼에 마우스를 올린 뒤 키를 누르면 보조 키, 마우스 버튼, 휠을 포함하여 지정됩니다. 오른쪽 클릭으로 해제하며, 취소 또는 Esc로 되돌립니다."
L["Per-bar text, borders, backgrounds, orientation and growth, the Retail button animations and visibility engine, and Bar 1 modifier paging."] = "바별 글자, 테두리, 배경, 방향, 확장, 리테일 버튼 애니메이션과 표시 여부 엔진, 바 1 보조 키 페이지 전환."
L["Shift+1 shows as S1, Control+1 as C1, mouse buttons as M4 and the wheel as MwU/MwD"] = "Shift+1은 S1, Control+1은 C1, 마우스 버튼은 M4, 휠은 MwU/MwD로 표시됩니다"
L["Shrink the bag bar to a single backpack button"] = "가방 바를 배낭 버튼 하나로 줄입니다"
L["Square micro menu and bag bar, flat XP and reputation bars and movable buffs and debuffs"] = "사각형 마이크로 메뉴와 가방 바, 평면 경험치 및 평판 바, 이동 가능한 강화 및 약화 효과"
L["Bar 1 paging arrows change the page without the \"blocked from an action only available to the Blizzard UI\" message."] = "바 1 페이지 화살표가 \"blocked from an action only available to the Blizzard UI\" 메시지 없이 페이지를 바꿉니다."
L["Changing stance no longer reveals a duplicate Blizzard stance and pet bar."] = "태세를 바꿀 때 더 이상 중복된 블리자드 태세 바와 소환수 바가 나타나지 않습니다."
L["Spells can be dropped on Bar 1 while the Blizzard bar art is hidden."] = "블리자드 바 그림이 숨겨져 있어도 주문을 바 1에 놓을 수 있습니다."
L["Player Buffs keep growing downward as rows are added."] = "플레이어 강화 효과가 줄이 추가될 때 계속 아래로 확장됩니다."
L["The XP and reputation bars no longer error on their first update."] = "경험치 및 평판 바가 첫 갱신 시 더 이상 오류를 일으키지 않습니다."
L["Create Soulstone reminders, including custom spell reminders, only appear for Warlocks."] = "영혼석 창조 알림은 사용자 지정 주문 알림을 포함하여 흑마법사에게만 표시됩니다."
L["A Holy-only reminder for your Seal of Wisdom, including when another seal is active."] = "다른 문장이 활성화된 경우를 포함하여 지혜의 문장에 대한 신성 전용 알림."
L["One click casts your group buff, such as Fortitude, Gift of the Wild or Arcane Brilliance, at its highest rank on the first member missing it."] = "클릭 한 번으로 인내, 야생의 선물, 신비한 지능 같은 그룹 강화 효과를 최고 등급으로 효과가 없는 첫 번째 그룹원에게 시전합니다."
L["Auras, presences, aspects, shields, weapon imbues, poisons, pets, Soulstone and Healthstone, plus flask, elixir and food with bag counts."] = "오라, 기운, 상, 보호막, 무기 강화, 독, 소환수, 영혼석과 생명석, 그리고 가방 수량이 표시되는 영약, 비약, 음식."
L["Reminder sounds include SharedMedia sounds, even from packs that load later"] = "알림 소리에 나중에 불러오는 묶음을 포함한 SharedMedia 소리가 포함됩니다"
L["World, normal and heroic dungeons and raids, or in combat, with Show Below timers"] = "야외, 일반 및 영웅 던전과 공격대, 또는 전투 중, 남은 시간 기준 타이머"
L["Talent reminders for Wrath zones and your current instance"] = "리치 왕의 분노 지역과 현재 인스턴스에 대한 특성 알림"
L["Your own aura ID reminders and a healer mana Ready Check Warning"] = "직접 지정한 오라 ID 알림과 힐러 마나 준비 확인 경고"
L["Middle-click hides a reminder until the next loading screen"] = "가운데 클릭하면 다음 로딩 화면까지 알림을 숨깁니다"
L["Turning off Runeforging now hides the Death Knight rune reminder."] = "룬 벼리기를 끄면 이제 죽음의 기사 룬 알림이 숨겨집니다."
L["Adding zones to an older talent reminder no longer errors, and the new zones apply right away."] = "이전 특성 알림에 지역을 추가해도 더 이상 오류가 발생하지 않으며, 새 지역이 즉시 적용됩니다."
L["A coin in the bag header marks items as junk: click it, then click items. Grey and marked items go to a Junk category, and a Sell Junk button appears next to the coin at merchants. Its cog adds a coin badge on marked items."] = "가방 상단의 동전으로 아이템을 잡동사니로 표시합니다: 동전을 클릭한 다음 아이템을 클릭하세요. 회색 아이템과 표시한 아이템은 잡동사니 분류로 들어가며, 상인에게서는 동전 옆에 잡동사니 판매 버튼이 나타납니다. 톱니바퀴에서 표시한 아이템에 동전 배지를 추가할 수 있습니다."
L["Bag keybinds open and close the existing layout during combat. Layout refreshes wait until combat ends."] = "가방 단축키는 전투 중에도 기존 배치를 열고 닫습니다. 배치 갱신은 전투가 끝날 때까지 기다립니다."
L["A sidebar with All Items, OneBag and MultiBag views, pinned and recent items, Retail categories for Wrath items and your own categories."] = "모든 아이템, 통합 가방, 가방 별로 보기와 고정 및 최근 아이템, 리치 왕의 분노 아이템을 위한 리테일 분류, 사용자 분류가 있는 사이드바."
L["OneBag merges stacks and sorts by bag type, MultiBag sorts each bag, with Sort to Bottom and Randomize."] = "통합 가방은 묶음을 합치고 가방 종류별로 정렬하며, 가방 별로는 각 가방을 정렬합니다. 아래로 정렬과 무작위 정렬을 지원합니다."
L["A cog beside the search opens the Bags options, or the Bank page at the bank"] = "검색창 옆의 톱니바퀴로 가방 설정을, 은행에서는 은행 페이지를 엽니다"
L["Each saved character in the Characters list has an x to delete its data"] = "캐릭터 목록의 저장된 각 캐릭터에 데이터를 삭제하는 x가 있습니다"
L["Quality borders, quest marks, item level, BoE text, set names and dimmed junk"] = "품질 테두리, 퀘스트 표시, 아이템 레벨, 착용 시 귀속 글자, 세트 이름, 흐리게 표시된 잡동사니"
L["Group the bank by category, with a sidebar"] = "사이드바와 함께 은행을 분류별로 묶습니다"
L["With Enable Bags off, the default bag functions are no longer replaced, avoiding blocked action errors from tainted bag code."] = "가방 활성화를 끄면 기본 가방 함수가 더 이상 교체되지 않아, 오염된 가방 코드로 인한 동작 차단 오류를 방지합니다."
L["Opening the Characters list no longer errors."] = "캐릭터 목록을 열 때 더 이상 오류가 발생하지 않습니다."
L["Gold sale ads with websites or cash prices, including 5000G=20 bucks and disguised W.W.W addresses, are filtered by default in your selected chat scopes."] = "웹사이트나 현금 가격이 포함된 골드 판매 광고(5000G=20 bucks 및 위장된 W.W.W 주소 포함)는 선택한 대화 범위에서 기본적으로 필터링됩니다."
L["Unsupported server channel notices such as NOT_IN_LFG no longer cause the native chat formatter to error."] = "NOT_IN_LFG 같은 지원되지 않는 서버 채널 알림이 더 이상 기본 대화 서식 처리기에서 오류를 일으키지 않습니다."
L["Optional spam filtering with a repeat window, sender matching and public, group or whisper controls."] = "반복 간격, 발신자 일치, 공개, 그룹, 귓속말 제어를 갖춘 선택적 스팸 필터."
L["Background, divider, input position, Retail border and tabs over the native dock, plus a sidebar with friends, guild, copy, channels and settings."] = "기본 도킹 위의 배경, 구분선, 입력 위치, 리테일 테두리 및 탭과, 친구, 길드, 복사, 채널, 설정이 있는 사이드바."
L["Retail timestamps, short channel names, class colored names, link tooltips, whisper sounds, saved chat history and Retail URL and copy windows."] = "리테일 시간 표시, 짧은 채널 이름, 직업 색상 이름, 링크 툴팁, 귓속말 소리, 저장된 대화 기록, 리테일 URL 및 복사 창."
L["Show Hidden Messages lists the last 200 lines the spam filter hid this session, with time, reason, channel and sender. Clear Filter History is now Reset Repeat Memory."] = "숨긴 메시지 표시는 이번 세션에 스팸 필터가 숨긴 마지막 200줄을 시간, 이유, 채널, 발신자와 함께 보여줍니다. 필터 기록 지우기는 이제 반복 기억 초기화입니다."
L["The trade ad preset also hides LFW (looking for work) crafting ads."] = "거래 광고 프리셋이 LFW(일감 구함) 제작 광고도 숨깁니다."
L["Right-click the chat in Unlock Mode to open its Display settings"] = "잠금 해제 모드에서 대화창을 우클릭하면 표시 설정이 열립니다"
L["Restyled chat bubbles with per-channel toggles and hiding in instances"] = "채널별 토글과 인스턴스 내 숨기기를 지원하는 새 스타일의 말풍선"
L["The chat fades after a delay and comes back on mouseover"] = "대화창이 일정 시간 후 흐려지고 마우스를 올리면 다시 나타납니다"
L["Copy Chat copies the chat tab you are looking at instead of the last tab you right-clicked, which could show \"(No chat history)\"."] = "대화 복사가 마지막으로 우클릭한 탭이 아니라 보고 있는 대화 탭을 복사하므로, \"(No chat history)\"가 표시되지 않습니다."
L["Fixed a \"SetPoint(): is dependent on this\" error when styling some NPC chat bubbles."] = "일부 NPC 말풍선에 스타일을 적용할 때 발생하던 \"SetPoint(): is dependent on this\" 오류를 수정했습니다."
L["The guild recruitment filter no longer hides raid ads that mention a guild, such as \"<Frost> LF 1 heal ICC25\"; only LF guild phrases count."] = "길드 모집 필터가 \"<Frost> LF 1 heal ICC25\"처럼 길드가 언급된 공격대 광고를 더 이상 숨기지 않습니다. 길드 구함 문구만 해당됩니다."
L["GM whispers and messages are never hidden by the spam filter."] = "GM 귓속말과 메시지는 스팸 필터에 의해 절대 숨겨지지 않습니다."
L["Spam filter keywords ignore case for accented letters too, so promoção also hides PROMOÇÃO."] = "스팸 필터 키워드가 악센트가 있는 글자도 대소문자를 구분하지 않으므로, promoção는 PROMOÇÃO도 숨깁니다."
L["The trade ad and guild recruitment filters follow the Public Chat setting, and the spam filter does no work while every filter is off."] = "거래 광고와 길드 모집 필터가 공개 대화 설정을 따르며, 모든 필터가 꺼져 있으면 스팸 필터는 아무 작업도 하지 않습니다."
L["The sidebar shows on first load, and tabs and toggles update right away."] = "사이드바가 처음 불러올 때 표시되며, 탭과 토글이 즉시 갱신됩니다."
L["The main chat keeps its Unlock Mode position instead of being reset by the dock."] = "주 대화창이 도킹에 의해 초기화되지 않고 잠금 해제 모드 위치를 유지합니다."
L["A saved chat opacity of 0 resets once to the Retail default."] = "저장된 대화 투명도가 0이면 한 번 리테일 기본값으로 초기화됩니다."
L["Square, rectangular, circle and textured circle maps, with border size, opacity, textured styles and custom, accent or class colors."] = "사각형, 직사각형, 원형, 텍스처 원형 지도로, 테두리 크기, 투명도, 텍스처 스타일, 사용자 지정, 강조 또는 직업 색상을 지원합니다."
L["Addon buttons collect into the Retail flyout with a grid, grow direction and Shift-drag Free Move."] = "애드온 버튼이 격자, 확장 방향, Shift-끌기 자유 이동을 갖춘 리테일 펼침 메뉴로 모입니다."
L["A vanilla ring and zone banner with native zoom buttons"] = "기본 확대/축소 버튼이 있는 오리지널 고리와 지역 배너"
L["Clock and zone boxes in ten positions, plus coordinates, FPS and latency, and difficulty text"] = "10가지 위치의 시계 및 지역 상자, 좌표, FPS와 지연 시간, 난이도 글자"
L["Guild and friends at a glance; left-click whispers, right-click invites"] = "길드와 친구를 한눈에 확인합니다. 왼쪽 클릭은 귓속말, 오른쪽 클릭은 초대입니다"
L["Menu actions open Blizzard windows through secure calls, avoiding blocked action errors."] = "메뉴 동작이 보안 호출로 블리자드 창을 열어 동작 차단 오류를 방지합니다."
L["Pick Classic WoW UI for Damage Meters on the Style page: each window gets the classic tooltip border, a tooltip header band and vanilla header icons, and keeps every EllesmereUI meter feature."] = "모양 페이지에서 데미지 미터기에 클래식 WoW UI를 선택하세요: 각 창에 클래식 툴팁 테두리, 툴팁 머리글 띠, 오리지널 머리글 아이콘이 적용되며, 모든 EllesmereUI 미터기 기능이 유지됩니다."
L["A spell's breakdown tooltip shows its Spell ID, and each spell row in the detailed window ends with its ID."] = "주문의 세부 내역 툴팁에 주문 ID가 표시되며, 상세 창의 각 주문 행 끝에 ID가 표시됩니다."
L["Consumed shield absorbs count toward Healing Done and HPS when the caster can be identified, with an Absorbs Done view."] = "시전자를 확인할 수 있으면 소모된 보호막 흡수량이 치유량과 HPS에 포함되며, 흡수량 보기도 제공됩니다."
L["Flat body, accent header, Atrocity bars and header icons for Settings, Segment, Meter Type and Reset, with up to five windows."] = "평면 본체, 강조 머리글, Atrocity 바, 설정, 구간, 미터기 유형, 초기화 머리글 아이콘으로 최대 다섯 개의 창을 지원합니다."
L["Up to 15 spells and the top three targets on hover, death recaps with health at each hit, and a per-player focus view."] = "마우스 오버 시 최대 15개의 주문과 상위 3개 대상, 각 타격 시 생명력이 포함된 죽음 요약, 플레이어별 집중 보기."
L["SharedMedia bar textures load whether a profile stores them in Damage Meters or EllesmereUI format"] = "SharedMedia 바 텍스처는 프로필이 데미지 미터기 형식이든 EllesmereUI 형식이든 불러와집니다"
L["An icon strip and bar window of your casts, including failed and interrupted ones"] = "실패하거나 차단된 시전을 포함한 내 시전의 아이콘 띠와 바 창"
L["A standalone combat timer with its own Unlock Mode element"] = "자체 잠금 해제 모드 요소를 가진 독립 전투 타이머"
L["Windows snap to each other; locked windows cannot move, resize or close"] = "창끼리 서로 붙으며, 잠긴 창은 이동, 크기 조절, 닫기를 할 수 없습니다"
L["Keybinds for Reset Data and Show / Hide Windows"] = "데이터 초기화 및 창 표시 / 숨기기 단축키"
L["Specialization icons from talent data and paced group inspection"] = "특성 데이터 기반의 전문화 아이콘과 속도를 조절한 그룹 살펴보기"
L["Load an action menu only in your primary or secondary talent group, and let two menus share one keybind across specs."] = "동작 메뉴를 주 특성 또는 보조 특성 그룹에서만 불러오고, 두 메뉴가 특성 간에 단축키 하나를 공유할 수 있습니다."
L["Hold a key, point or scroll to choose, release to fire. Up to 16 palettes of 20 entries in ring, arc, fan or grid layouts."] = "키를 누른 채 가리키거나 스크롤하여 선택하고, 놓으면 실행합니다. 고리, 호, 부채꼴, 격자 배치로 항목 20개짜리 팔레트를 최대 16개까지 지원합니다."
L["An Action Menu entry fans out up to 8 actions from another palette, one level out from the ring."] = "동작 메뉴 항목은 다른 팔레트의 동작을 최대 8개까지 고리에서 한 단계 바깥으로 펼칩니다."
L["Accent, class or custom color for the selected entry, needle and nested highlight"] = "선택한 항목, 바늘, 중첩 강조에 강조 색상, 직업 색상 또는 사용자 지정 색상"
L["Set the gap between a nested menu and its entry, and the nested icon size"] = "중첩 메뉴와 해당 항목 사이의 간격과 중첩 아이콘 크기를 설정합니다"
L["Reverse which way a wheel tick moves the selection"] = "휠 한 칸이 선택을 이동하는 방향을 반대로 합니다"
L["Assign Key captures the next key with modifiers and asks before rebinding"] = "키 지정은 보조 키를 포함한 다음 키 입력을 받고, 다시 지정하기 전에 확인합니다"
L["Keep the menu open on release and fire with a Select key"] = "키를 놓아도 메뉴를 열어 두고 선택 키로 실행합니다"
L["Red when out of range, blue when short of power, grey when unusable"] = "사거리 밖이면 빨간색, 자원이 부족하면 파란색, 사용할 수 없으면 회색"
L["Elite and rare marks. Always in the same slot as the Quest Indicator."] = "정예 및 희귀 표시입니다. 항상 퀘스트 표시기와 같은 슬롯에 있습니다."
L["Marks mobs for your active quests. Always in the same slot as the Rare Indicator."] = "진행 중인 퀘스트의 대상 몹을 표시합니다. 항상 희귀 표시기와 같은 슬롯에 있습니다."
L["Quest Indicator"] = "퀘스트 표시기"
L["Rare and Quest Indicators"] = "희귀 및 퀘스트 표시기"
L["Rare Indicator"] = "희귀 표시기"
L["Rare/Quest Indicator"] = "희귀/퀘스트 표시기"
L["The Boss Icon slot is now the Retail Rare/Quest Indicator. It marks elites and rares, and mobs your active quests still need. Pick Rare Indicator, Quest Indicator or both in Core Positions; the slot cog adds Show In Instances."] = "우두머리 아이콘 슬롯이 이제 리테일의 희귀/퀘스트 표시기가 됩니다. 정예와 희귀 몹, 그리고 진행 중인 퀘스트에 아직 필요한 몹을 표시합니다. 핵심 위치에서 희귀 표시기, 퀘스트 표시기 또는 둘 다를 선택하세요. 슬롯 톱니바퀴에서 인스턴스에서 표시를 설정할 수 있습니다."
L["Crowd Control"] = "군중 제어"
L["Crowd Control Slot"] = "군중 제어 슬롯"
L["Debuffs + CC"] = "약화 효과 + 군중 제어"
L["Crowd control on enemies (stuns, fears, polymorphs, roots, silences) gets its own Core Positions slot, from any caster, as on Retail. Or pick Debuffs + CC to show it first in the debuff row."] = "적에게 걸린 군중 제어(기절, 공포, 변이, 이동 불가, 침묵)가 리테일처럼 시전자와 관계없이 핵심 위치에 자체 슬롯을 갖습니다. 또는 약화 효과 + 군중 제어를 선택하면 약화 효과 줄의 맨 앞에 표시됩니다."
L["A dark block no longer appears to the left of the health bar and grows as health drops (the heal absorb overlay, which 3.3.5 does not have)."] = "생명력 바 왼쪽에 생명력이 줄수록 커지는 어두운 블록이 더 이상 나타나지 않습니다 (3.3.5에는 없는 치유 흡수 오버레이)."
